/// Returns `x` limited to the closed range `[lo, hi]`:
/// `lo` if `x < lo`, `hi` if `x > hi`, otherwise `x`.
pub fn clamp(x: i64, lo: i64, hi: i64) -> i64 {
    if x < lo {
        lo
    } else if x > hi {
        hi
    } else {
        x
    }
}

#[cfg(test)]
mod tests {
    use super::clamp;
    use proptest::prelude::*;

    #[test]
    fn below_range_returns_lo() {
        assert_eq!(clamp(1, 5, 10), 5);
        assert_eq!(clamp(i64::MIN, 0, 100), 0);
        assert_eq!(clamp(-50, -10, -1), -10);
    }

    #[test]
    fn above_range_returns_hi() {
        assert_eq!(clamp(11, 5, 10), 10);
        assert_eq!(clamp(i64::MAX, 0, 100), 100);
        assert_eq!(clamp(50, 10, 20), 20);
    }

    #[test]
    fn inside_range_returns_x() {
        assert_eq!(clamp(7, 5, 10), 7);
        assert_eq!(clamp(0, -100, 100), 0);
        assert_eq!(clamp(i64::MIN, i64::MIN, i64::MIN), i64::MIN);
        assert_eq!(clamp(i64::MAX, i64::MAX, i64::MAX), i64::MAX);
    }

    #[test]
    fn boundaries_are_inclusive() {
        assert_eq!(clamp(5, 5, 10), 5);
        assert_eq!(clamp(10, 5, 10), 10);
        assert_eq!(clamp(i64::MIN, i64::MIN, i64::MAX), i64::MIN);
        assert_eq!(clamp(i64::MAX, i64::MIN, i64::MAX), i64::MAX);
    }

    proptest! {
        #[test]
        fn clamped_value_is_in_range_and_matches_spec(
            x in any::<i64>(),
            lo in any::<i64>(),
            hi in any::<i64>(),
        ) {
            prop_assume!(lo <= hi);
            let r = clamp(x, lo, hi);
            // Result always lies in the closed range.
            assert!(lo <= r && r <= hi);
            // Result matches the definition exactly.
            let expected = if x < lo { lo } else if x > hi { hi } else { x };
            assert_eq!(r, expected);
        }

        #[test]
        fn lo_eq_hi(x in any::<i64>(), v in any::<i64>()) {
            assert_eq!(clamp(x, v, v), v);
        }

        #[test]
        fn inside_values_pass_through(a in any::<i64>(), b in any::<i64>()) {
            // [min(a, b), max(a, b)] always contains both a and b; no arithmetic.
            let lo = a.min(b);
            let hi = a.max(b);
            assert_eq!(clamp(a, lo, hi), a);
            assert_eq!(clamp(b, lo, hi), b);
        }

        #[test]
        fn extremes(v in any::<i64>()) {
            assert_eq!(clamp(i64::MIN, v, v), v);
            assert_eq!(clamp(i64::MAX, v, v), v);
            assert_eq!(clamp(v, i64::MIN, i64::MAX), v);
        }
    }
}

//! Exact midpoint of two `i64` values: `floor((a + b) / 2)`,
//! where the exact sum `a + b` is computed (it always fits in `i128`).

/// Returns the mean of `a` and `b` rounded toward negative infinity,
/// i.e. `floor((a + b) / 2)` computed exactly.
///
/// The exact sum `a + b` may not fit in `i64`, so it is computed in `i128`
/// (which always holds the sum of two `i64` values) and then floor-divided
/// by 2 using Euclidean division (which rounds toward negative infinity
/// for a positive divisor). The result always fits in `i64` because the
/// average of two values in `i64::MIN..=i64::MAX` lies within that range.
pub fn midpoint(a: i64, b: i64) -> i64 {
    let s: i128 = a as i128 + b as i128;
    // `div_euclid` with a positive divisor equals the floor of the exact quotient.
    s.div_euclid(2) as i64
}

#[cfg(test)]
mod tests {
    use super::midpoint;
    use proptest::prelude::*;

    #[test]
    fn basic_cases() {
        assert_eq!(midpoint(0, 0), 0);
        assert_eq!(midpoint(1, 1), 1);
        assert_eq!(midpoint(1, 2), 1); // floor(3/2) = 1
        assert_eq!(midpoint(2, 1), 1);
        assert_eq!(midpoint(3, 4), 3); // floor(7/2) = 3
        assert_eq!(midpoint(2, 4), 3); // exact 3
        assert_eq!(midpoint(0, 1), 0); // floor(1/2)
        assert_eq!(midpoint(0, -1), -1); // floor(-1/2)
        assert_eq!(midpoint(-1, 0), -1);
        assert_eq!(midpoint(-1, 1), 0); // exact 0
        assert_eq!(midpoint(-1, -2), -2); // floor(-3/2)
        assert_eq!(midpoint(-2, -1), -2);
        assert_eq!(midpoint(-1, -1), -1);
        assert_eq!(midpoint(5, 5), 5);
        assert_eq!(midpoint(10, -2), 4); // exact 4
        assert_eq!(midpoint(9, -2), 3); // floor(7/2)
        assert_eq!(midpoint(-11, 2), -5); // floor(-9/2)
        assert_eq!(midpoint(-9, 2), -4); // floor(-7/2)
        assert_eq!(midpoint(-1, 2), 0); // floor(1/2)
        assert_eq!(midpoint(-3, 2), -1); // floor(-1/2)
        assert_eq!(midpoint(2, -3), -1);
        assert_eq!(midpoint(7, -2), 2); // floor(5/2)
        assert_eq!(midpoint(-7, 2), -3); // floor(-5/2)
    }

    #[test]
    fn extreme_cases() {
        let mn = i64::MIN;
        let mx = i64::MAX;
        assert_eq!(midpoint(mn, mn), mn);
        assert_eq!(midpoint(mx, mx), mx);
        // mn + mx == -1 -> floor(-1/2) == -1
        assert_eq!(midpoint(mn, mx), -1);
        assert_eq!(midpoint(mx, mn), -1);
        // mn + (mn + 1) == 2*mn + 1 -> floor == mn
        assert_eq!(midpoint(mn, mn + 1), mn);
        assert_eq!(midpoint(mn + 1, mn), mn);
        // mn + (mn + 2) == 2*mn + 2 -> mn + 1
        assert_eq!(midpoint(mn, mn + 2), mn + 1);
        // mx + (mx - 1) == 2*mx - 1 -> floor == mx - 1
        assert_eq!(midpoint(mx, mx - 1), mx - 1);
        // mx + (mx - 2) == 2*mx - 2 -> mx - 1
        assert_eq!(midpoint(mx, mx - 2), mx - 1);
        // Sums that would overflow i64 in both directions:
        assert_eq!(midpoint(mn, 0), mn / 2); // -2^62
        assert_eq!(midpoint(mx, 0), mx / 2); // 2^62
        // mn + (mx - 1) = -2 -> floor(-2/2) = -1
        assert_eq!(midpoint(mn, mx - 1), -1);
        // mx + (mn + 1) = 1 -> floor(1/2) = 0
        assert_eq!(midpoint(mx, mn + 1), 0);
        // mx + (mx - 3) = 2*mx - 3 -> floor = mx - 2
        assert_eq!(midpoint(mx, mx - 3), mx - 2);
        // mn + (mn + 3) = 2*mn + 3 -> floor = mn + 1
        assert_eq!(midpoint(mn, mn + 3), mn + 1);
    }

    #[test]
    fn midpoint_of_same_is_identity() {
        for v in [i64::MIN, -8, -1, 0, 1, 8, i64::MAX - 1, i64::MAX] {
            assert_eq!(midpoint(v, v), v);
        }
    }

    proptest! {
        /// floor((a+b)/2) is the unique integer r with 2r <= a+b <= 2r+1
        /// (exact i128 arithmetic; i128 cannot overflow on these sums).
        #[test]
        fn prop_exact_floor(a: i64, b: i64) {
            let r = midpoint(a, b) as i128;
            let s: i128 = a as i128 + b as i128;
            prop_assert!(2 * r <= s);
            prop_assert!(s <= 2 * r + 1);
        }

        #[test]
        fn prop_commutative(a: i64, b: i64) {
            prop_assert_eq!(midpoint(a, b), midpoint(b, a));
        }

        #[test]
        fn prop_reflexive(a: i64) {
            prop_assert_eq!(midpoint(a, a), a);
        }

        /// The rounded mean must lie between the operands (inclusive).
        #[test]
        fn prop_between_ordinates(a: i64, b: i64) {
            if a <= b {
                let r = midpoint(a, b);
                prop_assert!(a <= r && r <= b);
            } else {
                let r = midpoint(a, b);
                prop_assert!(b <= r && r <= a);
            }
        }

        /// Shifting both operands by 2k shifts the floor mean by 2k.
        #[test]
        fn prop_shift(a: i64, b: i64, k: i32) {
            let da = (k as i64) * 2;
            let a2 = a.checked_add(da);
            let b2 = b.checked_add(da);
            if let (Some(a2), Some(b2)) = (a2, b2) {
                let r2 = midpoint(a2, b2);
                // sum shifts by 2 * da = 4k, so floor mean shifts by 2k
                let expected = midpoint(a, b).checked_add(da);
                if let Some(expected) = expected {
                    prop_assert_eq!(r2, expected);
                }
            }
        }

        /// Independent floor-division-by-2 reference using div/rem in i128.
        #[test]
        fn prop_reference(a: i64, b: i64) {
            let s: i128 = a as i128 + b as i128;
            let q = s / 2;
            let ref_r = if s % 2 < 0 { q - 1 } else { q };
            prop_assert_eq!(midpoint(a, b) as i128, ref_r);
        }
    }
}

/// Add the elements of `a` from left to right, starting from 0, where every
/// single addition saturates: if the exact running total would exceed
/// `i64::MAX` it becomes `i64::MAX`, if it would fall below `i64::MIN` it
/// becomes `i64::MIN`. Returns the final running total.
pub fn sat_sum(a: &[i64]) -> i64 {
    a.iter().fold(0i64, |acc, &x| acc.saturating_add(x))
}

#[cfg(test)]
mod tests {
    use super::sat_sum;
    use proptest::prelude::*;

    #[test]
    fn empty_slice_is_zero() {
        assert_eq!(sat_sum(&[]), 0);
    }

    #[test]
    fn ordinary_values() {
        assert_eq!(sat_sum(&[1, 2, 3]), 6);
        assert_eq!(sat_sum(&[-1, -2, -3]), -6);
        assert_eq!(sat_sum(&[1, -1, 2, -2, 5]), 5);
        assert_eq!(sat_sum(&[i64::MAX]), i64::MAX);
        assert_eq!(sat_sum(&[i64::MIN]), i64::MIN);
        assert_eq!(sat_sum(&[i64::MAX, 1]), i64::MAX);
        assert_eq!(sat_sum(&[i64::MIN, -1]), i64::MIN);
    }

    #[test]
    fn saturation_semantics() {
        // MAX + MAX overflows, saturates to MAX; then MAX - 1 comes back in
        // range (saturation is per addition, not sticky across in-range steps).
        assert_eq!(sat_sum(&[i64::MAX, i64::MAX, -1]), i64::MAX - 1);
        assert_eq!(sat_sum(&[i64::MIN, i64::MIN, 1]), i64::MIN + 1);
        // Stays saturated while overflows keep happening.
        assert_eq!(sat_sum(&[i64::MAX, i64::MAX, i64::MAX]), i64::MAX);
        assert_eq!(sat_sum(&[i64::MIN, i64::MIN, i64::MIN]), i64::MIN);
        // MAX + MIN is exact (-1); so is MIN + MAX.
        assert_eq!(sat_sum(&[i64::MAX, i64::MIN]), -1);
        assert_eq!(sat_sum(&[i64::MIN, i64::MAX]), -1);
        // Exact boundary: MAX - 1 + 1 == MAX exactly (no overflow).
        assert_eq!(sat_sum(&[i64::MAX - 1, 1]), i64::MAX);
        assert_eq!(sat_sum(&[i64::MIN + 1, -1]), i64::MIN);
        // MAX - 1 + 2 overflows the exact running total, so it saturates.
        assert_eq!(sat_sum(&[i64::MAX - 1, 2]), i64::MAX);
        assert_eq!(sat_sum(&[i64::MIN + 1, -2]), i64::MIN);
        // -1 + MIN overflows down, saturating at MIN.
        assert_eq!(sat_sum(&[i64::MAX, i64::MIN, i64::MIN]), i64::MIN);
        // -1 + MAX is exact (MAX - 1).
        assert_eq!(sat_sum(&[i64::MIN, i64::MAX, i64::MAX]), i64::MAX - 1);
    }

    #[test]
    fn mixed_extremes() {
        // 10 -> -10 -> MAX-10 -> MAX (saturates) -> MAX + MIN = -1 (exact)
        assert_eq!(sat_sum(&[10, -20, i64::MAX, i64::MAX, i64::MIN]), -1);
        assert_eq!(sat_sum(&[i64::MIN, 5, 5]), i64::MIN + 10);
        assert_eq!(sat_sum(&[i64::MAX, -5, -5]), i64::MAX - 10);
        assert_eq!(sat_sum(&[0, 0, 0]), 0);
    }

    proptest! {
        #[test]
        fn no_panic_on_random_inputs(a: Vec<i64>) {
            // Must not panic (overflow / out-of-bounds / div-by-zero) on any input.
            let _ = sat_sum(&a);
        }

        #[test]
        fn matches_checked_reference(a: Vec<i64>) {
            // Reference model using checked arithmetic: the running total is
            // the previous total plus x, clamped to [i64::MIN, i64::MAX].
            let mut expected = 0i64;
            for &x in &a {
                match expected.checked_add(x) {
                    Some(v) => expected = v,
                    None => expected = if x > 0 { i64::MAX } else { i64::MIN },
                }
            }
            assert_eq!(sat_sum(&a), expected);
        }

        #[test]
        fn matches_i128_clamped_reference(a: Vec<i64>) {
            // Reference model in i128: clamp the running total after each step.
            // i128 cannot overflow here: |acc| <= 2^63 at the end of each step,
            // and adding one i64 keeps it within 2^64 << 2^127.
            let lo: i128 = i128::from(i64::MIN);
            let hi: i128 = i128::from(i64::MAX);
            let mut acc: i128 = 0;
            for &x in &a {
                acc = (acc + x as i128).clamp(lo, hi);
            }
            assert_eq!(sat_sum(&a), acc as i64);
        }

        #[test]
        fn all_extremes_do_not_panic(bits: Vec<bool>) {
            let a: Vec<i64> =
                bits.into_iter().map(|b| if b { i64::MAX } else { i64::MIN }).collect();
            let _ = sat_sum(&a);
        }
    }
}

/// Returns how many elements `x` of `a` satisfy `lo <= x <= hi` (both ends inclusive).
/// If `lo > hi` the answer is 0.
pub fn count_in_range(a: &[i64], lo: i64, hi: i64) -> usize {
    if lo > hi {
        return 0;
    }
    let mut count = 0usize;
    for &x in a {
        if lo <= x && x <= hi {
            count += 1;
        }
    }
    count
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn empty_slice() {
        assert_eq!(count_in_range(&[], 0, 10), 0);
        assert_eq!(count_in_range(&[], i64::MIN, i64::MAX), 0);
    }

    #[test]
    fn lo_gt_hi_returns_zero() {
        let a = vec![1, 2, 3, 4, 5];
        assert_eq!(count_in_range(&a, 5, 1), 0);
        assert_eq!(count_in_range(&a, i64::MAX, i64::MIN), 0);
        assert_eq!(count_in_range(&[1, 2, 3], 3, 2), 0);
    }

    #[test]
    fn inclusive_bounds() {
        let a = vec![1, 2, 3, 4, 5];
        assert_eq!(count_in_range(&a, 2, 4), 3);
        assert_eq!(count_in_range(&a, 1, 5), 5);
        assert_eq!(count_in_range(&a, 2, 2), 1);
    }

    #[test]
    fn no_matches() {
        let a = vec![10, 20, 30];
        assert_eq!(count_in_range(&a, 0, 5), 0);
        assert_eq!(count_in_range(&a, 31, 40), 0);
    }

    #[test]
    fn duplicates_and_negatives() {
        let a = vec![-5, -3, -3, 0, 3, 3, 3];
        assert_eq!(count_in_range(&a, -3, 3), 6);
        assert_eq!(count_in_range(&a, -5, -5), 1);
        assert_eq!(count_in_range(&a, i64::MIN, i64::MAX), 7);
    }

    #[test]
    fn extreme_values() {
        let a = vec![i64::MIN, i64::MAX, 0];
        assert_eq!(count_in_range(&a, i64::MIN, i64::MIN), 1);
        assert_eq!(count_in_range(&a, i64::MAX, i64::MAX), 1);
        assert_eq!(count_in_range(&a, i64::MIN, i64::MAX), 3);
        assert_eq!(count_in_range(&a, -1, 1), 1);
    }

    proptest! {
        #[test]
        fn prop_matches_bruteforce(
            a in prop::collection::vec(any::<i64>(), 0..64),
            lo in any::<i64>(),
            hi in any::<i64>(),
        ) {
            // Independent reference: naive loop with the condition written differently.
            let mut expected = 0usize;
            for x in &a {
                if !(*x < lo) && !(hi < *x) {
                    expected += 1;
                }
            }
            assert_eq!(count_in_range(&a, lo, hi), expected);
        }

        #[test]
        fn prop_inverted_range_is_zero(
            a in prop::collection::vec(any::<i64>(), 0..64),
            hi in i64::MIN..i64::MAX,
            gap in 1i64..=i64::MAX,
        ) {
            // lo = hi + gap, saturating: guarantees lo > hi with no overflow.
            let lo = hi.saturating_add(gap);
            assert!(lo > hi);
            assert_eq!(count_in_range(&a, lo, hi), 0);
        }

        #[test]
        fn prop_total_partition(
            a in prop::collection::vec(any::<i64>(), 0..64),
            pivot in any::<i64>(),
        ) {
            // Counting (-inf, pivot] and (pivot, +inf) must partition the slice.
            let left = count_in_range(&a, i64::MIN, pivot);
            let right = if pivot == i64::MAX {
                0
            } else {
                count_in_range(&a, pivot.wrapping_add(1), i64::MAX)
            };
            assert_eq!(left + right, a.len());
        }
    }
}

//! Returns the smallest index `i` such that `a[i]` is a largest element of `a`.

/// Return the first index at which the maximum value of `a` occurs.
///
/// The input domain guarantees `a` is non-empty.
pub fn first_max_index(a: &[i64]) -> usize {
    let mut best = 0;
    for i in 1..a.len() {
        if a[i] > a[best] {
            best = i;
        }
    }
    best
}

#[cfg(test)]
mod tests {
    use super::first_max_index;
    use proptest::prelude::*;

    #[test]
    fn single_element() {
        assert_eq!(first_max_index(&[42]), 0);
        assert_eq!(first_max_index(&[i64::MIN]), 0);
        assert_eq!(first_max_index(&[i64::MAX]), 0);
    }

    #[test]
    fn first_max_wins_on_duplicates() {
        assert_eq!(first_max_index(&[5, 1, 5, 2, 5]), 0);
        assert_eq!(first_max_index(&[1, 9, 3, 9, 7]), 1);
        assert_eq!(first_max_index(&[3, 3, 3, 3]), 0);
        assert_eq!(first_max_index(&[2, 2, 3, 3, 1, 3]), 2);
    }

    #[test]
    fn max_at_end() {
        assert_eq!(first_max_index(&[1, 2, 3, 4, 5]), 4);
        assert_eq!(first_max_index(&[-5, -4, -3, -2, -1]), 4);
    }

    #[test]
    fn all_negative() {
        assert_eq!(first_max_index(&[-7, -2, -9, -2, -3]), 1);
        assert_eq!(first_max_index(&[i64::MIN, i64::MIN]), 0);
    }

    #[test]
    fn extremes() {
        assert_eq!(first_max_index(&[i64::MIN, 0, i64::MAX, 0]), 2);
        assert_eq!(first_max_index(&[i64::MAX, i64::MIN, i64::MAX]), 0);
    }

    proptest! {
        #[test]
        fn prop_first_max_properties(v in prop::collection::vec(any::<i64>(), 1..1000)) {
            let idx = first_max_index(&v);
            // The element at idx is the maximum.
            let expected_max = *v.iter().max().unwrap();
            prop_assert_eq!(v[idx], expected_max);
            // It is the *first* maximum: everything before is strictly smaller.
            prop_assert!(v[..idx].iter().all(|&x| x < expected_max));
        }
    }
}

/// Return the largest index `i` such that `a[i]` is a smallest element of `a`.
///
/// That is, the index of the last occurrence of the minimum value.
/// `a` is guaranteed to be non-empty.
pub fn last_min_index(a: &[i64]) -> usize {
    let mut min = a[0];
    let mut idx = 0usize;
    for (i, &x) in a.iter().enumerate() {
        if x <= min {
            min = x;
            idx = i;
        }
    }
    idx
}

#[cfg(test)]
mod tests {
    use super::last_min_index;
    use proptest::prelude::*;

    #[test]
    fn single_element() {
        assert_eq!(last_min_index(&[42]), 0);
        assert_eq!(last_min_index(&[i64::MIN]), 0);
        assert_eq!(last_min_index(&[i64::MAX]), 0);
    }

    #[test]
    fn all_equal() {
        assert_eq!(last_min_index(&[7, 7, 7, 7]), 3);
    }

    #[test]
    fn min_at_front() {
        assert_eq!(last_min_index(&[1, 2, 3, 4]), 0);
    }

    #[test]
    fn min_at_back() {
        assert_eq!(last_min_index(&[4, 3, 2, 1]), 3);
    }

    #[test]
    fn min_in_middle_unique() {
        assert_eq!(last_min_index(&[5, 3, 1, 4, 2]), 2);
        assert_eq!(last_min_index(&[5, 4, 2, 1, 3]), 3);
    }

    #[test]
    fn min_repeated() {
        assert_eq!(last_min_index(&[2, 1, 2, 1, 3]), 3);
        assert_eq!(last_min_index(&[1, 2, 3, 1, 4, 1]), 5);
        assert_eq!(last_min_index(&[i64::MIN, 0, i64::MIN]), 2);
        assert_eq!(last_min_index(&[-5, -5, -4, -5]), 3);
    }

    #[test]
    fn two_elements() {
        assert_eq!(last_min_index(&[2, 1]), 1);
        assert_eq!(last_min_index(&[1, 2]), 0);
        assert_eq!(last_min_index(&[1, 1]), 1);
        assert_eq!(last_min_index(&[i64::MAX, i64::MIN]), 1);
        assert_eq!(last_min_index(&[i64::MIN, i64::MAX]), 0);
    }

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(2000))]
        #[test]
        fn prop_matches_reference_scan_full_range(
            a in prop::collection::vec(any::<i64>(), 1..=64)
        ) {
            let min = *a.iter().min().unwrap();
            let expected = a.iter().rposition(|&x| x == min).unwrap();
            prop_assert_eq!(last_min_index(&a), expected);
        }

        // Small value range forces many ties on the minimum.
        #[test]
        fn prop_matches_reference_scan_with_duplicates(
            a in prop::collection::vec(-5i64..=5, 1..=64)
        ) {
            let min = *a.iter().min().unwrap();
            let expected = a.iter().rposition(|&x| x == min).unwrap();
            prop_assert_eq!(last_min_index(&a), expected);
        }

        #[test]
        fn prop_returns_index_of_last_smallest(
            a in prop::collection::vec(any::<i64>(), 1..=64)
        ) {
            let idx = last_min_index(&a);
            let min = *a.iter().min().unwrap();
            // returned element is a minimum
            prop_assert_eq!(a[idx], min);
            // it is the *last* occurrence of the minimum
            prop_assert_eq!(idx, a.iter().rposition(|&x| x == min).unwrap());
        }
    }
}

//! Returns `true` exactly when every element of `a` is strictly smaller
//! than the next one (`a[i] < a[i + 1]` for every valid `i`).
//! Empty and one-element slices are strictly increasing.

pub fn strictly_increasing(a: &[i64]) -> bool {
    a.windows(2).all(|w| w[0] < w[1])
}

#[cfg(test)]
mod tests {
    use super::strictly_increasing;
    use proptest::prelude::*;

    #[test]
    fn empty_and_single() {
        assert!(strictly_increasing(&[]));
        assert!(strictly_increasing(&[0]));
        assert!(strictly_increasing(&[i64::MIN]));
        assert!(strictly_increasing(&[i64::MAX]));
    }

    #[test]
    fn basic_true_cases() {
        assert!(strictly_increasing(&[1, 2, 3]));
        assert!(strictly_increasing(&[5, 6]));
        assert!(strictly_increasing(&[-10, -5, 0, 1]));
        assert!(strictly_increasing(&[i64::MIN, i64::MAX]));
    }

    #[test]
    fn basic_false_cases() {
        assert!(!strictly_increasing(&[2, 1]));
        assert!(!strictly_increasing(&[1, 1]));
        assert!(!strictly_increasing(&[1, 2, 2, 3]));
        assert!(!strictly_increasing(&[3, 2, 1]));
        assert!(!strictly_increasing(&[1, 2, 3, 0]));
        assert!(!strictly_increasing(&[i64::MAX, i64::MIN]));
    }

    // Independent reference implementation written as an explicit loop.
    fn reference(v: &[i64]) -> bool {
        for i in 0..v.len().saturating_sub(1) {
            if !(v[i] < v[i + 1]) {
                return false;
            }
        }
        true
    }

    proptest! {
        #[test]
        fn prop_matches_reference(v in proptest::collection::vec(any::<i64>(), 0..64)) {
            assert_eq!(strictly_increasing(&v), reference(&v));
        }

        #[test]
        fn prop_consistent_with_sorted_order(v in proptest::collection::vec(any::<i64>(), 0..64)) {
            let mut sorted = v.clone();
            sorted.sort();
            // If the slice is strictly increasing it must already be the ascending sort.
            if strictly_increasing(&v) {
                prop_assert_eq!(&v, &sorted);
            }
            // Strictly increasing with all-distinct values is exactly the ascending sort.
            let all_distinct = v.windows(2).all(|w| w[0] != w[1]);
            if all_distinct {
                prop_assert_eq!(strictly_increasing(&v), v == sorted);
            }
        }

        #[test]
        fn prop_tail_preservation(v in proptest::collection::vec(any::<i64>(), 1..64)) {
            // A slice is strictly increasing iff its tail is and the first
            // element is smaller than the second.
            if v.len() >= 2 {
                prop_assert_eq!(
                    strictly_increasing(&v),
                    v[0] < v[1] && strictly_increasing(&v[1..])
                );
            } else {
                prop_assert!(strictly_increasing(&v));
            }
        }
    }
}

//! Binary search helpers.

/// Returns the smallest index `i` such that `a[i] >= t`, or `a.len()` if
/// every element is smaller than `t`.
///
/// `a` must be sorted in non-decreasing order. Uses binary search.
pub fn lower_bound(a: &[i64], t: i64) -> usize {
    let mut lo: usize = 0;
    let mut hi: usize = a.len();
    // Invariant: the answer lies in [lo, hi].
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if a[mid] >= t {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    lo
}

#[cfg(test)]
mod tests {
    use super::lower_bound;
    use proptest::prelude::*;

    #[test]
    fn empty_slice() {
        assert_eq!(lower_bound(&[], 0), 0);
        assert_eq!(lower_bound(&[], i64::MIN), 0);
        assert_eq!(lower_bound(&[], i64::MAX), 0);
    }

    #[test]
    fn single_element() {
        assert_eq!(lower_bound(&[5], 5), 0);
        assert_eq!(lower_bound(&[5], 4), 0);
        assert_eq!(lower_bound(&[5], 6), 1);
        assert_eq!(lower_bound(&[i64::MIN], i64::MIN), 0);
        assert_eq!(lower_bound(&[i64::MIN], i64::MIN + 1), 1);
        assert_eq!(lower_bound(&[i64::MAX], i64::MAX - 1), 0);
        assert_eq!(lower_bound(&[i64::MAX], i64::MAX), 0);
    }

    #[test]
    fn all_smaller_or_equal_cases() {
        let a = [1i64, 3, 5, 7, 9];
        // t <= first element -> 0
        assert_eq!(lower_bound(&a, -100), 0);
        assert_eq!(lower_bound(&a, 1), 0);
        // t between elements
        assert_eq!(lower_bound(&a, 2), 1);
        assert_eq!(lower_bound(&a, 4), 2);
        // t equals an element
        assert_eq!(lower_bound(&a, 5), 2);
        // t > last element -> len
        assert_eq!(lower_bound(&a, 9), 4);
        assert_eq!(lower_bound(&a, 10), 5);
        assert_eq!(lower_bound(&a, i64::MAX), 5);
    }

    #[test]
    fn duplicates() {
        let a = [2i64, 2, 2, 4, 4, 6, 6, 6, 9];
        assert_eq!(lower_bound(&a, 2), 0); // first occurrence
        assert_eq!(lower_bound(&a, 3), 3);
        assert_eq!(lower_bound(&a, 4), 3); // first of the 4s
        assert_eq!(lower_bound(&a, 6), 5); // first of the 6s
        assert_eq!(lower_bound(&a, 7), 8);
        assert_eq!(lower_bound(&a, 9), 8);
        assert_eq!(lower_bound(&a, 10), 9);
        assert_eq!(lower_bound(&a, 1), 0);
        assert_eq!(lower_bound(&a, 0), 0);
    }

    #[test]
    fn extremes() {
        let a = [i64::MIN, i64::MIN, 0, i64::MAX, i64::MAX];
        assert_eq!(lower_bound(&a, i64::MIN), 0);
        assert_eq!(lower_bound(&a, i64::MIN + 1), 2);
        assert_eq!(lower_bound(&a, 0), 2);
        assert_eq!(lower_bound(&a, 1), 3);
        assert_eq!(lower_bound(&a, i64::MAX), 3);
        assert_eq!(lower_bound(&a, i64::MAX - 1), 3);
        assert_eq!(lower_bound(&[i64::MIN; 4], i64::MAX), 4);
        assert_eq!(lower_bound(&[i64::MAX; 4], i64::MAX), 0);
    }

    /// Brute-force reference: linear scan for the first index with a[i] >= t.
    fn reference(a: &[i64], t: i64) -> usize {
        a.iter().position(|&x| x >= t).unwrap_or(a.len())
    }

    proptest! {
        #[test]
        fn matches_linear_scan_and_invariants(sorted in prop::collection::vec(any::<i64>(), 0..64).prop_map(|mut v| { v.sort_unstable(); v }), t in any::<i64>()) {
            let i = lower_bound(&sorted, t);
            // Matches brute force.
            prop_assert_eq!(i, reference(&sorted, t));
            // Matches std's partition_point over the same predicate.
            prop_assert_eq!(i, sorted.partition_point(|&x| x < t));
            // Characterizing property: a[i] >= t (when in bounds) and
            // a[i-1] < t (when i > 0).
            if i < sorted.len() {
                prop_assert!(sorted[i] >= t);
            }
            if i > 0 {
                prop_assert!(sorted[i - 1] < t);
            }
        }

        #[test]
        fn target_is_an_element(sorted in prop::collection::vec(any::<i64>(), 0..64).prop_map(|mut v| { v.sort_unstable(); v })) {
            prop_assume!(!sorted.is_empty());
            // For every element t = a[k], lower_bound lands on its first
            // occurrence (an index i <= k with a[i] == t and a[i-1] < t).
            for k in 0..sorted.len() {
                let t = sorted[k];
                let i = lower_bound(&sorted, t);
                prop_assert!(i <= k);
                prop_assert!(sorted[i] == t);
                if i > 0 {
                    prop_assert!(sorted[i - 1] < t);
                }
            }
            // Gaps just outside the value range, when they fit in i64.
            let first = sorted[0];
            let last = *sorted.last().unwrap();
            if last < i64::MAX {
                prop_assert_eq!(lower_bound(&sorted, last + 1), sorted.len());
            }
            if first > i64::MIN {
                prop_assert_eq!(lower_bound(&sorted, first - 1), 0);
            }
        }

        #[test]
        fn monotonic_in_target(sorted in prop::collection::vec(any::<i64>(), 0..64).prop_map(|mut v| { v.sort_unstable(); v })) {
            // As t increases, the returned index never decreases.
            let mut targets: Vec<i64> = sorted.iter().copied().collect();
            if sorted.first().map(|&f| f > i64::MIN).unwrap_or(false) {
                targets.push(sorted[0] - 1);
            }
            if sorted.last().map(|&l| l < i64::MAX).unwrap_or(false) {
                targets.push(*sorted.last().unwrap() + 1);
            }
            targets.push(i64::MAX);
            targets.sort_unstable();
            let mut prev = lower_bound(&sorted, i64::MIN);
            for &t in &targets {
                let i = lower_bound(&sorted, t);
                prop_assert!(i >= prev);
                prev = i;
            }
        }
    }
}

//! Floor division for i64: `div_floor(a, b)` is `a / b` rounded toward
//! negative infinity.
//!
//! Valid for `b != 0`, excluding the pair `(a, b) = (i64::MIN, -1)` whose
//! quotient (2^63) does not fit in an i64.

pub fn div_floor(a: i64, b: i64) -> i64 {
    let q = a / b; // truncates toward zero
    let r = a % b;
    // The truncating quotient q satisfies a = q*b + r with |r| < |b|.
    // If the remainder is nonzero and has the opposite sign of the divisor,
    // the true quotient is slightly past q away from zero, so the floor
    // is one less than the truncating quotient.
    if r != 0 && (r < 0) != (b < 0) {
        q - 1
    } else {
        q
    }
}

#[cfg(test)]
mod tests {
    use super::div_floor;
    use proptest::prelude::*;

    #[test]
    fn examples_from_spec() {
        assert_eq!(div_floor(7, 2), 3);
        assert_eq!(div_floor(-7, 2), -4);
        assert_eq!(div_floor(7, -2), -4);
        assert_eq!(div_floor(-7, -2), 3);
    }

    #[test]
    fn edge_cases() {
        // Dividend zero
        assert_eq!(div_floor(0, 1), 0);
        assert_eq!(div_floor(0, -1), 0);
        assert_eq!(div_floor(0, i64::MAX), 0);
        assert_eq!(div_floor(0, i64::MIN), 0);

        // Exact division (no adjustment)
        assert_eq!(div_floor(4, 2), 2);
        assert_eq!(div_floor(-4, 2), -2);
        assert_eq!(div_floor(4, -2), -2);
        assert_eq!(div_floor(-4, -2), 2);
        assert_eq!(div_floor(8, 4), 2);

        // Small divisor values
        assert_eq!(div_floor(1, -1), -1);
        assert_eq!(div_floor(-1, 1), -1);
        assert_eq!(div_floor(1, 1), 1);
        assert_eq!(div_floor(-1, -1), 1);
        assert_eq!(div_floor(-1, -2), 0); //  floor(0.5)
        assert_eq!(div_floor(1, -2), -1); // floor(-0.5)
        assert_eq!(div_floor(-1, 2), -1); // floor(-0.5)
        assert_eq!(div_floor(1, 2), 0); //  floor(0.5)

        // i64::MIN as dividend (b = -1 excluded by the domain)
        assert_eq!(div_floor(i64::MIN, 1), i64::MIN);
        assert_eq!(div_floor(i64::MIN, 2), i64::MIN / 2); // -2^62, exact
        assert_eq!(div_floor(i64::MIN, -2), i64::MIN / -2); // 2^62, exact
        assert_eq!(div_floor(i64::MIN, 3), -3_074_457_345_618_258_603);
        assert_eq!(div_floor(i64::MIN, -3), 3_074_457_345_618_258_602);
        assert_eq!(div_floor(i64::MIN, 10), -922_337_203_685_477_581);
        assert_eq!(div_floor(i64::MIN, -10), 922_337_203_685_477_580);
        assert_eq!(div_floor(i64::MIN, i64::MIN), 1);
        // floor(-2^63 / (2^63-1)) = floor(-1 - 1/(2^63-1)) = -2
        assert_eq!(div_floor(i64::MIN, i64::MAX), -2);

        // i64::MAX as dividend
        assert_eq!(div_floor(i64::MAX, -1), -i64::MAX);
        assert_eq!(div_floor(i64::MAX, 2), 4_611_686_018_427_387_903);
        assert_eq!(div_floor(i64::MAX, -2), -4_611_686_018_427_387_904);
        // floor((2^63-1) / (-2^63)) = floor(-1 + 1/2^63) = -1
        assert_eq!(div_floor(i64::MAX, i64::MIN), -1);
        // floor((2^63-1) / -2^31) = floor(-(2^32 - 1/2^31)) = -2^32
        assert_eq!(div_floor(i64::MAX, -1 << 31), -4_294_967_296);
        assert_eq!(div_floor(-i64::MAX, 1), -i64::MAX);
    }

    proptest! {
        #[test]
        fn floor_quotient_property(a in any::<i64>(), b in any::<i64>()) {
            prop_assume!(b != 0 && !(a == i64::MIN && b == -1));
            let (a128, b128) = (a as i128, b as i128);
            let q = div_floor(a, b) as i128;
            // The result must be either the truncating quotient or one less.
            let t = a128 / b128;
            prop_assert!(q == t || q == t - 1);
            // Correct "floor" interval for the remainder a - q*b:
            // for b > 0:  0 <= a - q*b < b
            // for b < 0:  b < a - q*b <= 0
            // (i128 throughout: q*b can exceed the i64 range, e.g.
            // div_floor(a, 2^62+1) * (2^62+1) for a near -2^63.)
            let r = a128 - q * b128;
            if b > 0 {
                prop_assert!(r >= 0 && r < b128);
            } else {
                prop_assert!(r > b128 && r <= 0);
            }
        }

        #[test]
        fn matches_i128_oracle(a in any::<i64>(), b in any::<i64>()) {
            prop_assume!(b != 0 && !(a == i64::MIN && b == -1));
            // Independent computation in i128: |a/b| < 2^63 for i64 inputs,
            // so the i128 quotient always fits back into i64, and
            // truncating division + the standard floor adjustment is an
            // exact oracle for the real quotient.
            let (qa, qb) = (a as i128, b as i128);
            let q = qa / qb;
            let r = qa % qb;
            let qf = if r != 0 && (r < 0) != (qb < 0) { q - 1 } else { q };
            prop_assert_eq!(div_floor(a, b), qf as i64);
        }

        #[test]
        fn matches_euclid_for_positive_divisor(a in any::<i64>(), b in 1..=i64::MAX) {
            let q = div_floor(a, b) as i128;
            // rem_euclid is by definition the "floor" remainder for b > 0.
            // i128 to avoid overflow in q*b.
            prop_assert_eq!(a as i128 - q * (b as i128), a.rem_euclid(b) as i128);
        }
    }
}

//! Floor-modulus arithmetic.

/// Returns `a - b * floor(a / b)`, the remainder of floor division.
///
/// The result is `0` or has the sign of `b`, and its absolute value is
/// strictly smaller than `|b|`.
///
/// # Examples
/// ```
/// assert_eq!(solution::mod_floor(7, 3), 1);
/// assert_eq!(solution::mod_floor(-7, 3), 2);
/// assert_eq!(solution::mod_floor(7, -3), -2);
/// assert_eq!(solution::mod_floor(-7, -3), -1);
/// ```
///
/// # Panics
/// Panics if `b == 0`.
pub fn mod_floor(a: i64, b: i64) -> i64 {
    if b == 0 {
        panic!("mod_floor: b must be nonzero");
    }
    // Every integer is a multiple of 1 or -1. Handling this up front also
    // avoids the one case where `a / b` or `a % b` could overflow
    // (a == i64::MIN, b == -1).
    if b == 1 || b == -1 {
        return 0;
    }
    let r = a % b; // Rust's `%`: same sign as `a`, |r| < |b|
    // If `r` and `b` disagree in sign, add `b` to bring it into the
    // floor-division range. Since |r| < |b| and the signs disagree,
    // `r + b` lies strictly between 0 and ±b and cannot overflow.
    if r != 0 && (r < 0) != (b < 0) {
        r + b
    } else {
        r
    }
}

#[cfg(test)]
mod tests {
    use super::mod_floor;
    use proptest::prelude::*;

    #[test]
    fn task_examples() {
        assert_eq!(mod_floor(7, 3), 1);
        assert_eq!(mod_floor(-7, 3), 2);
        assert_eq!(mod_floor(7, -3), -2);
        assert_eq!(mod_floor(-7, -3), -1);
    }

    #[test]
    fn basics() {
        assert_eq!(mod_floor(0, 5), 0);
        assert_eq!(mod_floor(0, -5), 0);
        assert_eq!(mod_floor(3, 7), 3);
        assert_eq!(mod_floor(-3, 7), 4);
        assert_eq!(mod_floor(3, -7), -4);
        assert_eq!(mod_floor(-3, -7), -3);
        assert_eq!(mod_floor(10, -4), -2);
        assert_eq!(mod_floor(-10, -4), -2);
        assert_eq!(mod_floor(10, 4), 2);
        assert_eq!(mod_floor(-10, 4), 2);
    }

    #[test]
    fn zeros_and_multiples() {
        assert_eq!(mod_floor(6, 3), 0);
        assert_eq!(mod_floor(-6, 3), 0);
        assert_eq!(mod_floor(6, -3), 0);
        assert_eq!(mod_floor(-6, -3), 0);
        assert_eq!(mod_floor(2, 3), 2);
        assert_eq!(mod_floor(-2, 3), 1);
        assert_eq!(mod_floor(2, -3), -1);
        assert_eq!(mod_floor(-2, -3), -2);
    }

    #[test]
    fn divisors_of_one() {
        assert_eq!(mod_floor(5, 1), 0);
        assert_eq!(mod_floor(-5, 1), 0);
        assert_eq!(mod_floor(5, -1), 0);
        assert_eq!(mod_floor(-5, -1), 0);
        assert_eq!(mod_floor(i64::MIN, 1), 0);
        assert_eq!(mod_floor(i64::MIN, -1), 0);
        assert_eq!(mod_floor(i64::MAX, 1), 0);
        assert_eq!(mod_floor(i64::MAX, -1), 0);
    }

    #[test]
    fn extremes() {
        // a = i64::MIN
        assert_eq!(mod_floor(i64::MIN, 2), 0);
        assert_eq!(mod_floor(i64::MIN, -2), 0);
        assert_eq!(mod_floor(i64::MIN, 3), 1); // 2^63 % 3 == 2, so MIN % 3 (floor) == 1
        assert_eq!(mod_floor(i64::MIN, -3), -2);
        assert_eq!(mod_floor(i64::MIN, i64::MAX), i64::MAX - 1);
        assert_eq!(mod_floor(i64::MIN, i64::MAX - 1), i64::MAX - 3);
        assert_eq!(mod_floor(i64::MIN, 4), 0);
        assert_eq!(mod_floor(i64::MIN, -4), 0);
        assert_eq!(mod_floor(i64::MIN, -i64::MAX), -1);
        // a = i64::MAX
        assert_eq!(mod_floor(i64::MAX, 3), 1); // 2^63 - 1 == 1 (mod 3)
        assert_eq!(mod_floor(i64::MAX, -3), -2);
        assert_eq!(mod_floor(i64::MAX, 2), 1);
        assert_eq!(mod_floor(i64::MAX, -2), -1);
        assert_eq!(mod_floor(i64::MAX, i64::MAX - 1), 1);
        assert_eq!(mod_floor(i64::MAX, 1 - i64::MAX), i64::MIN + 3);
    }

    proptest! {
        #[test]
        fn matches_wider_reference(
            a in any::<i64>(),
            b in any::<i64>().prop_map(|b| if b == 0 { 1 } else { b })
        ) {
            // Reference computed in i128 (no overflow possible there).
            let (ai, bi): (i128, i128) = (a as i128, b as i128);
            let q = ai / bi; // truncating toward zero
            let rem = ai % bi;
            let q_floor = if (rem < 0 && bi > 0) || (rem > 0 && bi < 0) { q - 1 } else { q };
            let expected = ai - bi * q_floor;
            // expected is in (-|b|, |b|), hence fits in i64.
            prop_assert!((expected as i64) as i128 == expected);
            prop_assert_eq!(mod_floor(a, b), expected as i64);
        }

        #[test]
        fn sign_and_magnitude(
            a in any::<i64>(),
            b in any::<i64>().prop_map(|b| if b == 0 { 1 } else { b })
        ) {
            let r = mod_floor(a, b);
            // r is 0 or has the sign of b.
            prop_assert!(r == 0 || (r < 0) == (b < 0));
            // |r| < |b|, written without abs() to avoid MIN overflow.
            prop_assert!((b > 0 && r >= 0 && r < b) || (b < 0 && r <= 0 && r > b));
            // r == a (mod b), checked in i128 to avoid overflow in i64.
            let (ai, bi, ri): (i128, i128, i128) = (a as i128, b as i128, r as i128);
            prop_assert_eq!((ai - ri) % bi, 0);
        }

        #[test]
        fn identity_laws(
            a in any::<i64>(),
            b in any::<i64>().prop_map(|b| if b == 0 { 1 } else { b })
        ) {
            let r = mod_floor(a, b);
            let (ai, bi, ri): (i128, i128, i128) = (a as i128, b as i128, r as i128);
            // a - r is divisible by b; the quotient is the floor quotient.
            prop_assert_eq!((ai - ri) % bi, 0);
            let q = (ai - ri) / bi;
            // q == floor(a / b)  <=>  q*b <= a < (q+1)*b  (b > 0),
            // or the reversed inequalities when b < 0. All exact in i128.
            if bi > 0 {
                prop_assert!(q * bi <= ai);
                prop_assert!(ai < (q + 1) * bi);
            } else {
                prop_assert!((q + 1) * bi <= ai);
                prop_assert!(ai < q * bi);
            }
        }
    }
}

//! Largest sum of a non-empty contiguous subarray.

/// Returns the largest sum of a non-empty contiguous run `a[i..=j]` (i <= j) of `a`.
///
/// `a` is guaranteed to be non-empty. Elements are in `[-1_000_000_000, 1_000_000_000]`
/// and `a.len() <= 1_000_000`, so the true sum is bounded by `1e15` and fits easily
/// in `i64` (no intermediate overflow is possible in the computation).
///
/// Uses Kadane's algorithm: O(n) time, O(1) extra space.
pub fn max_subarray(a: &[i64]) -> i64 {
    // a is guaranteed non-empty.
    let mut best = a[0];
    let mut cur = a[0];
    for &x in &a[1..] {
        // Either extend the previous run or start a new one at x.
        cur = cur.max(0) + x;
        if cur > best {
            best = cur;
        }
    }
    best
}

#[cfg(test)]
mod tests {
    use super::max_subarray;
    use proptest::prelude::*;

    #[test]
    fn single_element() {
        assert_eq!(max_subarray(&[5]), 5);
        assert_eq!(max_subarray(&[-7]), -7);
        assert_eq!(max_subarray(&[0]), 0);
    }

    #[test]
    fn all_negative_picks_largest_single() {
        assert_eq!(max_subarray(&[-3, -1, -4, -1, -5]), -1);
        assert_eq!(max_subarray(&[-100, -200, -50]), -50);
    }

    #[test]
    fn classic_examples() {
        assert_eq!(max_subarray(&[-2, 1, -3, 4, -1, 2, 1, -5, 4]), 6);
        assert_eq!(max_subarray(&[5, 4, -1, 7, 8]), 23);
        assert_eq!(max_subarray(&[1]), 1);
        assert_eq!(max_subarray(&[1, 2, 3, 4]), 10);
        assert_eq!(max_subarray(&[0, 0, 0, 0]), 0);
        assert_eq!(max_subarray(&[8, -19, 20, 7]), 27);
    }

    fn brute_force(a: &[i64]) -> i64 {
        let mut best = i64::MIN;
        for i in 0..a.len() {
            let mut s = 0i64;
            for j in i..a.len() {
                s += a[j];
                if s > best {
                    best = s;
                }
            }
        }
        best
    }

    proptest! {
        #![proptest_config(ProptestConfig { cases: 500, ..ProptestConfig::default() })]
        #[test]
        fn matches_brute_force_small(
            a in prop::collection::vec(-1_000..=1_000i64, 1..=60)
        ) {
            prop_assert_eq!(max_subarray(&a), brute_force(&a));
        }

        #[test]
        fn matches_brute_force_wide_values(
            a in prop::collection::vec(-1_000_000_000i64..=1_000_000_000, 1..=40)
        ) {
            prop_assert_eq!(max_subarray(&a), brute_force(&a));
        }
    }

    #[test]
    fn extremes_no_overflow() {
        // 1_000_000 elements of 1_000_000_000 -> sum 1e15, fits in i64.
        let big_pos = vec![1_000_000_000i64; 1_000_000];
        assert_eq!(max_subarray(&big_pos), 1_000_000_000_000_000);

        let big_neg = vec![-1_000_000_000i64; 1_000_000];
        assert_eq!(max_subarray(&big_neg), -1_000_000_000);

        // Mix: negative prefix, then a huge positive block.
        let mut mixed = vec![-1_000_000_000i64; 500_000];
        mixed.extend(std::iter::repeat(1_000_000_000i64).take(500_000));
        assert_eq!(max_subarray(&mixed), 500_000_000_000_000);
    }
}

//! Returns the second largest distinct value of a slice.

/// Returns the second largest distinct value of `a`: the largest value that is
/// strictly smaller than the maximum of `a`.
///
/// If `a` has fewer than two distinct values (including when `a` is empty),
/// returns `i64::MIN`.
pub fn second_max(a: &[i64]) -> i64 {
    let mut max: Option<i64> = None;
    let mut second: Option<i64> = None;

    for &x in a {
        match (max, second) {
            (None, _) => {
                max = Some(x);
            }
            (Some(m), _) if x > m => {
                second = Some(m);
                max = Some(x);
            }
            (Some(m), s) if x < m && s.map_or(true, |s| x > s) => {
                second = Some(x);
            }
            // x == max, or x <= current second: nothing to do.
            _ => {}
        }
    }

    second.unwrap_or(i64::MIN)
}

#[cfg(test)]
mod tests {
    use super::second_max;
    use proptest::prelude::*;

    /// Reference implementation via sorting.
    fn reference(a: &[i64]) -> i64 {
        let mut v: Vec<i64> = a.iter().copied().collect();
        v.sort_unstable();
        v.dedup();
        if v.len() >= 2 {
            v[v.len() - 2]
        } else {
            i64::MIN
        }
    }

    #[test]
    fn empty_returns_min() {
        assert_eq!(second_max(&[]), i64::MIN);
    }

    #[test]
    fn single_element_returns_min() {
