        assert_eq!(second_max(&[i64::MIN]), i64::MIN);
        assert_eq!(second_max(&[i64::MAX]), i64::MIN);
    }

    #[test]
    fn all_equal_returns_min() {
        assert_eq!(second_max(&[7, 7, 7, 7]), i64::MIN);
        assert_eq!(second_max(&[i64::MIN, i64::MIN]), i64::MIN);
        assert_eq!(second_max(&[i64::MAX, i64::MAX, i64::MAX]), i64::MIN);
    }

    #[test]
    fn basic_cases() {
        assert_eq!(second_max(&[1, 2, 3]), 2);
        assert_eq!(second_max(&[3, 2, 1]), 2);
        assert_eq!(second_max(&[2, 3, 1]), 2);
        assert_eq!(second_max(&[1, 3, 2]), 2);
        assert_eq!(second_max(&[5, 3, 4]), 4);
        assert_eq!(second_max(&[10, 10, 9, 10, 8]), 9);
        assert_eq!(second_max(&[9, 10, 10, 10, 8]), 9);
        assert_eq!(second_max(&[1, 2]), 1);
        assert_eq!(second_max(&[2, 1]), 1);
    }

    #[test]
