        }

        #[test]
        fn prop_matches_reference_small_values(a in proptest::collection::vec(-5i64..=5, 0..100)) {
            prop_assert_eq!(second_max(&a), reference(&a));
        }

        #[test]
        fn prop_matches_reference_extremes(a in proptest::collection::vec(
            prop_oneof![
                any::<i64>(),
                Just(i64::MIN),
                Just(i64::MAX),
                Just(i64::MAX - 1),
                Just(i64::MIN + 1),
            ],
            0..100
        )) {
            prop_assert_eq!(second_max(&a), reference(&a));
        }

        #[test]
        fn prop_second_max_property(a in proptest::collection::vec(any::<i64>(), 0..100)) {
            let r = second_max(&a);
            let distinct: Vec<i64> = {
                let mut v: Vec<i64> = a.to_vec();
                v.sort_unstable();
                v.dedup();
                v
            };
            if distinct.len() < 2 {
                prop_assert_eq!(r, i64::MIN);
            } else {
