                prop_assert!(a.contains(&r));
            }
        }
    }
}

/// Rotate `a` to the right by `k` positions in place:
/// the element at index `i` moves to index `(i + k) % a.len()`.
///
/// `k` may be larger than `a.len()`; an empty slice stays empty.
pub fn rotate_right(a: &mut [i64], k: usize) {
    let n = a.len();
    if n == 0 {
        return;
    }
    let k = k % n;
    if k == 0 {
        return;
    }
    // Right rotation by k == reverse all, reverse first k, reverse rest.
    // O(n) time, O(1) extra space; all indices stay within 0..n so no overflow.
    a.reverse();
    a[..k].reverse();
    a[k..].reverse();
}

#[cfg(test)]
mod tests {
    use super::rotate_right;
    use proptest::prelude::*;

    #[test]
    fn empty_slice_stays_empty() {
        let mut a: [i64; 0] = [];
        rotate_right(&mut a, 0);
        rotate_right(&mut a, usize::MAX);
        assert_eq!(a, []);
    }

    #[test]
    fn single_element_unchanged() {
        let mut a = [42_i64];
        rotate_right(&mut a, usize::MAX);
        assert_eq!(a, [42]);
    }

    #[test]
    fn k_zero_noop() {
        let mut a = [1, 2, 3, 4, 5];
        rotate_right(&mut a, 0);
        assert_eq!(a, [1, 2, 3, 4, 5]);
    }

    #[test]
    fn k_equal_to_len_noop() {
        let mut a = [9, 8, 7, 6];
        rotate_right(&mut a, 4);
        assert_eq!(a, [9, 8, 7, 6]);
    }

    #[test]
    fn k_larger_than_len() {
        let mut a = [1, 2, 3, 4, 5];
        rotate_right(&mut a, 7); // 7 % 5 == 2
        assert_eq!(a, [4, 5, 1, 2, 3]);
        let mut b = [1, 2, 3, 4, 5];
        rotate_right(&mut b, 12); // 12 % 5 == 2
        assert_eq!(b, [4, 5, 1, 2, 3]);
    }

    #[test]
    fn huge_k() {
        // 2^64 ≡ 1 (mod 3), so usize::MAX % 3 == 0 -> noop.
        let mut d = [7, 1, 5];
        rotate_right(&mut d, usize::MAX);
        assert_eq!(d, [7, 1, 5]);
        // And (usize::MAX - 1) % 3 == 2 -> right by 2: [7,1,5] -> [1,5,7].
        let mut e = [7, 1, 5];
        rotate_right(&mut e, usize::MAX - 1);
        assert_eq!(e, [1, 5, 7]);
    }

    #[test]
    fn classic_cases() {
        let mut a = [1, 2, 3, 4, 5, 6, 7];
        rotate_right(&mut a, 3);
        assert_eq!(a, [5, 6, 7, 1, 2, 3, 4]);

        let mut b = [1, 2, 3, 4, 5];
        rotate_right(&mut b, 1);
        assert_eq!(b, [5, 1, 2, 3, 4]);

        let mut c = [1, 2, 3, 4, 5];
        rotate_right(&mut c, 4); // right by 4 == left by 1
        assert_eq!(c, [2, 3, 4, 5, 1]);

        let mut e = [2, 3];
        rotate_right(&mut e, 1);
        assert_eq!(e, [3, 2]);
        rotate_right(&mut e, 1); // back to start
        assert_eq!(e, [2, 3]);
    }

    proptest! {
        #[test]
        fn matches_reference(
            a in prop::collection::vec(any::<i64>(), 0..32),
            k in 0usize..usize::MAX,
        ) {
            let old = a.clone();
            let n = old.len();
            let k_rem = if n == 0 { 0 } else { k % n };
            let mut v = a;
            rotate_right(&mut v, k);
            // Element that was at i moves to (i + k) % n,
            // i.e. new[j] = old[(j + n - k_rem) % n].
            let expected: Vec<i64> = (0..n).map(|j| old[(j + n - k_rem) % n]).collect();
            prop_assert_eq!(v, expected);
        }

        #[test]
        fn permutation_preserved(a in prop::collection::vec(any::<i64>(), 0..32), k in 0usize..usize::MAX) {
            let old = a.clone();
            let mut sorted_old = old.clone();
            sorted_old.sort_unstable();
            let mut v = a;
            rotate_right(&mut v, k);
            let mut sorted_v = v.clone();
            sorted_v.sort_unstable();
            prop_assert_eq!(sorted_v, sorted_old);
        }

        #[test]
        fn double_rotation_identity(
            a in prop::collection::vec(any::<i64>(), 0..32),
            k in 0usize..usize::MAX,
        ) {
            let old = a.clone();
            let n = old.len();
            let mut v = a;
            rotate_right(&mut v, k);
            let k_rem = if n == 0 { 0 } else { k % n };
            rotate_right(&mut v, n.saturating_sub(k_rem)); // total multiple of n
            prop_assert_eq!(v, old);
        }

        #[test]
        fn specific_huge_ks(
            a in prop::collection::vec(any::<i64>(), 0..40),
        ) {
            for k in [0usize, 1, usize::MAX, usize::MAX - 1, usize::MAX - 2, usize::MAX / 2, usize::MAX / 2 + 1] {
                let old = a.clone();
                let n = old.len();
                let k_rem = if n == 0 { 0 } else { k % n };
                let mut v = a.clone();
                rotate_right(&mut v, k);
                let expected: Vec<i64> = (0..n).map(|j| old[(j + n - k_rem) % n]).collect();
                prop_assert_eq!(v, expected);
            }
        }
    }
}

//! In-place deduplication of a sorted slice.

/// `a` is sorted in non-decreasing order.
///
/// In place, move the distinct values of `a` to the front in increasing
/// order, set every remaining position to 0, and return the number of
/// distinct values.
pub fn dedup_sorted(a: &mut [i64]) -> usize {
    let n = a.len();
    if n == 0 {
        return 0;
    }
    let mut k: usize = 1; // number of distinct values written so far
    let mut i: usize = 1;
    while i < n {
        if a[i] != a[k - 1] {
            a[k] = a[i];
            k += 1;
        }
        i += 1;
    }
    for slot in &mut a[k..] {
        *slot = 0;
    }
    k
}

#[cfg(test)]
mod tests {
    use super::dedup_sorted;

    #[test]
    fn empty() {
        let mut a: [i64; 0] = [];
        assert_eq!(dedup_sorted(&mut a), 0);
        assert_eq!(a, []);
    }

    #[test]
    fn single() {
        let mut a = [7i64];
        assert_eq!(dedup_sorted(&mut a), 1);
        assert_eq!(a, [7]);

        let mut a = [0i64];
        assert_eq!(dedup_sorted(&mut a), 1);
        assert_eq!(a, [0]);
    }

    #[test]
    fn all_equal() {
        let mut a = [3i64, 3, 3, 3];
        assert_eq!(dedup_sorted(&mut a), 1);
        assert_eq!(a, [3, 0, 0, 0]);

        let mut a = [0i64, 0, 0];
        assert_eq!(dedup_sorted(&mut a), 1);
        assert_eq!(a, [0, 0, 0]);
    }

    #[test]
    fn no_duplicates() {
        let mut a = [-5i64, -1, 0, 2, 9];
        assert_eq!(dedup_sorted(&mut a), 5);
        assert_eq!(a, [-5, -1, 0, 2, 9]);
    }

    #[test]
    fn duplicates_at_end() {
        let mut a = [1i64, 2, 2, 2];
        assert_eq!(dedup_sorted(&mut a), 2);
        assert_eq!(a, [1, 2, 0, 0]);
    }

    #[test]
    fn zeros_in_the_middle_are_a_value() {
        // 0 here is a genuine distinct value, not just fill.
        let mut a = [-4i64, -4, 0, 0, 5];
        assert_eq!(dedup_sorted(&mut a), 3);
        assert_eq!(a, [-4, 0, 5, 0, 0]);
    }

    #[test]
    fn negatives_and_i64_extremes() {
        let mut a = [i64::MIN, i64::MIN, 0, 0, i64::MAX];
        assert_eq!(dedup_sorted(&mut a), 3);
        assert_eq!(a, [i64::MIN, 0, i64::MAX, 0, 0]);
    }

    #[test]
    fn only_zero_tail_filled() {
        let mut a = [1i64, 1, 1, 1, 1];
        assert_eq!(dedup_sorted(&mut a), 1);
        assert_eq!(a, [1, 0, 0, 0, 0]);
    }

    // Reference computation on a copy.
    fn reference(orig: &[i64]) -> (usize, Vec<i64>) {
        let mut distinct: Vec<i64> = Vec::new();
        for &x in orig {
            if distinct.last() != Some(&x) {
                distinct.push(x);
            }
        }
        let k = distinct.len();
        let mut out = orig.to_vec();
        for (slot, v) in out.iter_mut().zip(distinct.iter().chain(std::iter::repeat(&0))) {
            *slot = *v;
        }
        (k, out)
    }

    use proptest::prelude::*;

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(256))]

        #[test]
        fn sorted_dedup_matches_reference(v in proptest::collection::vec(any::<i64>(), 0..=64)) {
            // Make it sorted non-decreasing.
            let mut orig = v;
            orig.sort_unstable();
            let (expect_k, expect) = reference(&orig);
            let mut a = orig.clone();
            let k = dedup_sorted(&mut a);
            prop_assert_eq!(k, expect_k);
            prop_assert_eq!(&a[..], &expect[..]);
        }

        #[test]
        fn sorted_dedup_small_values(v in proptest::collection::vec(0..=6i64, 0..=32)) {
            let mut orig = v;
            orig.sort_unstable();
            let (expect_k, expect) = reference(&orig);
            let mut a = orig.clone();
            let k = dedup_sorted(&mut a);
            prop_assert_eq!(k, expect_k);
            prop_assert_eq!(&a[..], &expect[..]);
        }
    }
}

//! Move all zero elements of a slice to the end, in place,
//! while preserving the relative order of the non-zero elements.

pub fn move_zeros(a: &mut [i64]) {
    let mut next_nonzero = 0usize;
    for i in 0..a.len() {
        if a[i] != 0 {
            a.swap(next_nonzero, i);
            next_nonzero += 1;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::move_zeros;
