    }

    #[test]
    fn negative_and_large_values() {
        let mut a = [-42, 0, i64::MAX, 0, i64::MIN, 0, 1];
        move_zeros(&mut a);
        assert_eq!(a, [-42, i64::MAX, i64::MIN, 1, 0, 0, 0]);
    }

    proptest! {
        #![proptest_config(ProptestConfig {
            cases: 500,
            ..ProptestConfig::default()
        })]

        /// Result must be the non-zero elements (original order) followed
        /// by as many zeros, and the multiset of values must be preserved.
        #[test]
        fn property_preserves_nonzero_order_and_moves_zeros_to_end(
            vals in prop::collection::vec(any::<i64>(), 0..64)
        ) {
            let original = vals.clone();
            let mut a = vals;
            move_zeros(&mut a);

            // Expected arrangement: non-zeros in original relative order,
            // then the zeros.
            let expected: Vec<i64> = {
                let zeros = original.iter().filter(|&&v| v == 0).count();
                let mut e: Vec<i64> = original.iter().copied().filter(|&v| v != 0).collect();
                e.extend(std::iter::repeat(0).take(zeros));
                e
            };
            prop_assert_eq!(&a, &expected);

            // Same multiset of values (nothing lost or duplicated).
            let mut sorted_a: Vec<i64> = a.to_vec();
            sorted_a.sort_unstable();
            let mut sorted_o: Vec<i64> = original;
            sorted_o.sort_unstable();
            prop_assert_eq!(&sorted_a, &sorted_o);
        }

