        #[test]
        fn property_idempotent(
            vals in prop::collection::vec(any::<i64>(), 0..32)
        ) {
            let mut a = vals;
            move_zeros(&mut a);
            let after_first = a.to_vec();
            move_zeros(&mut a);
            prop_assert_eq!(&a, &after_first);
        }
    }
}

/// Returns the greatest common divisor of `a` and `b`.
///
/// The result is never negative. `gcd(0, 0) == 0` and `gcd(a, 0) == |a|`.
///
/// # Panics
///
/// Does not panic for the supported input domain: `a` and `b` are `i64`
/// values greater than `i64::MIN`, so their absolute values fit in `i64`.
pub fn gcd(a: i64, b: i64) -> i64 {
    // The domain guarantees a > i64::MIN and b > i64::MIN, so abs() cannot overflow.
    let (mut a, mut b) = (a.unsigned_abs() as i64, b.unsigned_abs() as i64);
    while b != 0 {
        let t = a % b;
        a = b;
        b = t;
    }
    a
}

#[cfg(test)]
mod tests {
    use super::gcd;
    use proptest::prelude::*;

    #[test]
    fn basic_cases() {
        assert_eq!(gcd(0, 0), 0);
        assert_eq!(gcd(0, 5), 5);
        assert_eq!(gcd(5, 0), 5);
        assert_eq!(gcd(0, -5), 5);
        assert_eq!(gcd(-5, 0), 5);
        assert_eq!(gcd(12, 18), 6);
        assert_eq!(gcd(-12, 18), 6);
        assert_eq!(gcd(12, -18), 6);
        assert_eq!(gcd(-12, -18), 6);
        assert_eq!(gcd(7, 13), 1);
        assert_eq!(gcd(1, 1), 1);
        assert_eq!(gcd(-1, 1), 1);
        assert_eq!(gcd(100, 10), 10);
        assert_eq!(gcd(10, 100), 10);
    }

    #[test]
    fn edge_values() {
        // Domain excludes i64::MIN, so i64::MAX and -i64::MAX are in range.
        assert_eq!(gcd(i64::MAX, i64::MAX), i64::MAX);
        assert_eq!(gcd(-i64::MAX, i64::MAX), i64::MAX);
        assert_eq!(gcd(i64::MAX, 0), i64::MAX);
        assert_eq!(gcd(0, -i64::MAX), i64::MAX);
        // 2^62 and 2^62 - 2 share gcd 2
        let big = 1_i64 << 62;
        assert_eq!(gcd(big, big - 2), 2);
    }

    fn reference_gcd(a: i64, b: i64) -> i64 {
        // Reference computed in i128 so no intermediate can overflow;
        // for the domain the result always fits back into i64.
        let (mut x, mut y) = (a.unsigned_abs() as i128, b.unsigned_abs() as i128);
        while y != 0 {
            let t = x % y;
            x = y;
            y = t;
        }
        x as i64
    }

    proptest! {
        #[test]
        fn prop_matches_reference(a in any::<i64>().prop_map(|v| v + 1), b in any::<i64>().prop_map(|v| v + 1)) {
            // Shift values up by 1 to avoid i64::MIN, keeping coverage of the rest of the domain.
            assert_eq!(gcd(a, b), reference_gcd(a, b));
            assert!(gcd(a, b) >= 0);
        }

        #[test]
        fn prop_divides_both(a in any::<i64>().prop_map(|v| v + 1), b in any::<i64>().prop_map(|v| v + 1)) {
            let g = gcd(a, b);
            assert!(g >= 0);
            if a != 0 { assert_eq!((a as i128).rem_euclid(g as i128), 0); }
            if b != 0 { assert_eq!((b as i128).rem_euclid(g as i128), 0); }
        }

        #[test]
        fn prop_commutative(a in any::<i64>().prop_map(|v| v + 1), b in any::<i64>().prop_map(|v| v + 1)) {
            assert_eq!(gcd(a, b), gcd(b, a));
        }

        #[test]
        fn prop_zero_identity(a in any::<i64>().prop_map(|v| v + 1)) {
            assert_eq!(gcd(a, 0), a.unsigned_abs() as i64);
            assert_eq!(gcd(0, a), a.unsigned_abs() as i64);
        }

        #[test]
        fn prop_small_values(a in -1000i32..=1000i32, b in -1000i32..=1000i32) {
            // Check against a naive trial-division definition.
            let (x, y): (u64, u64) = ((a as i64).unsigned_abs(), (b as i64).unsigned_abs());
            // Any common divisor d satisfies d <= x (if x > 0) and d <= y (if y > 0).
            let mut upper = 0;
            if x != 0 { upper = x; }
            if y != 0 { upper = upper.min(y); }
            let mut expected = 0;
            for d in (1..=upper).rev() {
                if x % d == 0 && y % d == 0 {
                    expected = d;
                    break;
                }
            }
            assert_eq!(gcd(a as i64, b as i64), expected as i64);
        }
    }
}

/// Returns the integer square root of `n`: the largest `r >= 0` such that
/// `r * r <= n`, computed exactly.
///
/// The input domain is `n >= 0`.
pub fn isqrt(n: i64) -> i64 {
    // floor(sqrt(i64::MAX)) = 3_037_000_499, since
    //   3_037_000_499^2 = 9_223_372_030_926_249_001 <= i64::MAX
    //   3_037_000_500^2 = 9_223_372_037_000_250_000 >  i64::MAX
    // So the answer never exceeds MAX_ROOT, and no intermediate product
    // can overflow even u128.
    const MAX_ROOT: u128 = 3_037_000_499;

    let n = n.max(0) as u128;
    let (mut lo, mut hi) = (0u128, n.min(MAX_ROOT));
    // Invariant: the answer a = max { r : r^2 <= n } lies in [lo, hi].
    while lo < hi {
        let mid = lo + (hi - lo + 1) / 2;
        if mid * mid <= n {
            lo = mid;
        } else {
            hi = mid - 1;
        }
    }
    lo as i64
}

#[cfg(test)]
mod tests {
    use super::isqrt;

    #[test]
    fn small_values_brute_force() {
        for n in 0..=100_000i64 {
            let mut r = 0i64;
            while (r + 1) * (r + 1) <= n {
                r += 1;
            }
            assert_eq!(isqrt(n), r, "n = {n}");
        }
    }

    #[test]
    fn known_values() {
        // Squares computed in-code so no constant is ever hand-wrong.
        let a = 999i64;
        let b = 1_000i64;
        let c = 31_622i64;
        let d = 1_000_000_000i64;
        let cases: &[(i64, i64)] = &[
            (0, 0),
            (1, 1),
            (2, 1),
            (3, 1),
            (4, 2),
            (5, 2),
            (8, 2),
            (9, 3),
            (15, 3),
            (16, 4),
            (25, 5),
            (99, 9),
            (a * a - 1, a - 1),
            (a * a, a),
            (b * b - 1, b - 1),
            (b * b, b),
            (c * c - 1, c - 1),
            (c * c, c),
            (d * d - 1, d - 1), // 10^18 - 1
            (d * d, d),         // 10^18
            (i64::MAX, 3_037_000_499),
        ];
        for &(n, want) in cases {
            assert_eq!(isqrt(n), want, "n = {n}");
        }
    }

    #[test]
    fn max_root_boundary() {
        let r: i128 = 3_037_000_499;
        let r2 = r * r;
        assert_eq!(r2, 9_223_372_030_926_249_001i128);
        assert!((r + 1) * (r + 1) > i64::MAX as i128);
        // Transition from r-1 to r happens exactly at r^2:
        assert_eq!(isqrt(r2 as i64), 3_037_000_499);
        assert_eq!(isqrt(r2 as i64 - 1), 3_037_000_498);
        // Below (r-1)^2 and one past it: still root r-1, since the gap
        // up to r^2 is 2r-1.
        let lm1: i128 = (r - 1) * (r - 1);
        assert_eq!(isqrt(lm1 as i64), 3_037_000_498);
        assert_eq!(isqrt(lm1 as i64 + 1), 3_037_000_498);
        assert_eq!(isqrt(lm1 as i64 - 1), 3_037_000_497);
    }

    proptest::proptest! {
        // The full spec: r*r <= n < (r+1)^2, with all products in i128
        // so no overflow can occur in the check itself.
        #[test]
        fn spec(n in 0u64..=i64::MAX as u64) {
            let n = n as i64;
            let r = isqrt(n);
            assert!(r >= 0);
            let r = r as i128;
            let n = n as i128;
            assert!(r * r <= n, "r = {r}, n = {n}");
            assert!((r + 1) * (r + 1) > n, "r = {r}, n = {n}");
        }

        // Every exact square n = s^2 must give back s.
        #[test]
        fn exact_squares(s in 0u64..=3_037_000_499u64) {
            let n = ((s as i128) * (s as i128)) as i64;
            assert_eq!(isqrt(n), s as i64);
        }

        // Every value just below a square gives the previous root.
        #[test]
        fn below_squares(s in 1u64..=3_037_000_499u64) {
            let n = ((s as i128) * (s as i128) - 1) as i64;
            assert_eq!(isqrt(n), (s - 1) as i64);
        }
    }
}

/// Returns the number of decimal digits of `|n|`.
/// The sign does not count; 0 has one digit.
///
/// Works for every `i64` value, including `i64::MIN`
/// (whose magnitude cannot be represented as a positive `i64`).
pub fn count_digits(n: i64) -> i64 {
    // `unsigned_abs` handles i64::MIN without panicking and never
    // produces a sign character, so the string length equals the
    // number of digits of |n|.
    n.unsigned_abs().to_string().len() as i64
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn expected(n: i64) -> i64 {
        // Independent reference: count digits of |n| via u128 arithmetic
        // (avoids the i64::MIN overflow issue in naive abs()).
        let mag: u128 = if n == i64::MIN {
            (i64::MAX as u128) + 1
        } else {
            n.unsigned_abs() as u128
        };
        if mag == 0 {
            return 1;
        }
        let mut c = 0;
        let mut m = mag;
        while m > 0 {
            m /= 10;
            c += 1;
        }
        c
    }

    #[test]
    fn basics() {
        assert_eq!(count_digits(0), 1);
        assert_eq!(count_digits(1), 1);
        assert_eq!(count_digits(-1), 1);
        assert_eq!(count_digits(9), 1);
        assert_eq!(count_digits(-9), 1);
        assert_eq!(count_digits(10), 2);
        assert_eq!(count_digits(-10), 2);
        assert_eq!(count_digits(99), 2);
        assert_eq!(count_digits(-99), 2);
        assert_eq!(count_digits(100), 3);
        assert_eq!(count_digits(123456), 6);
        assert_eq!(count_digits(-123456), 6);
    }

    #[test]
    fn extremes() {
        assert_eq!(count_digits(i64::MAX), 19);
        assert_eq!(count_digits(i64::MIN), 19);
        assert_eq!(count_digits(1_000_000_000_000_000_000), 19);
        assert_eq!(count_digits(-1_000_000_000_000_000_000), 19);
        assert_eq!(count_digits(999_999_999_999_999_999), 18);
        assert_eq!(count_digits(1_000_000_000_000_000_000 - 1), 18);
    }

    proptest! {
        #[test]
        fn prop_matches_reference(n in any::<i64>()) {
            assert_eq!(count_digits(n), expected(n));
        }

        #[test]
        fn prop_sign_independent(n in any::<i64>()) {
            // For every n where -n is defined (i.e. n != i64::MIN),
            // the digit count of n and -n must agree.
            if n != i64::MIN {
                assert_eq!(count_digits(n), count_digits(-n));
            }
        }

        #[test]
        fn prop_digit_bounds(n in any::<i64>()) {
            let d = count_digits(n);
            assert!((1..=19).contains(&d));
        }

        #[test]
        fn prop_magnitude_boundaries(k in 0u64..u64::MAX) {
            // 10^k has k+1 digits (for k up to 18, within i64 range).
            if k <= 18 {
                let v = (10i64.pow(k as u32)).try_into().unwrap();
                assert_eq!(count_digits(v), (k + 1) as i64);
                assert_eq!(count_digits(-v), (k + 1) as i64);
                if k >= 1 {
                    assert_eq!(count_digits(v - 1), k as i64);
                    assert_eq!(count_digits(1 - v), k as i64);
                }
            }
        }
    }
}

//! Sum of the half-open range `[i, j)` of a slice.

/// Returns `a[i] + a[i + 1] + ... + a[j - 1]`, the sum of the half-open
/// range `[i, j)` of `a` (0 when `i == j`).
///
/// # Preconditions (input domain)
/// `i <= j <= a.len()`.
pub fn range_sum(a: &[i64], i: usize, j: usize) -> i64 {
    // In the given domain, a sum of at most 1_000_000 elements, each with
    // absolute value at most 1_000_000_000_000, has absolute value at most
    // 10^18, which fits comfortably in i64 (max ~9.22 * 10^18).
    a[i..j].iter().sum()
}

#[cfg(test)]
mod tests {
    use super::range_sum;
    use proptest::prelude::*;

    fn elems(max_len: usize) -> impl Strategy<Value = Vec<i64>> {
        prop::collection::vec(-1_000_000_000_000i64..=1_000_000_000_000i64, 0..max_len)
    }

    /// Given arbitrary `p, q <= max_len`, derive a valid `(i, j, a)` with
    /// `i <= j <= a.len()` by padding `a` with zeros if needed.
    fn valid_case(a: Vec<i64>, p: usize, q: usize) -> (Vec<i64>, usize, usize) {
        let i = p.min(q);
        let j = p.max(q);
        let mut a = a;
        while a.len() < j {
            a.push(0);
        }
        (a, i, j)
    }

    #[test]
    fn empty_range_is_zero() {
        let a: &[i64] = &[3, 1, 4, 1, 5];
        for k in 0..=a.len() {
            assert_eq!(range_sum(a, k, k), 0, "empty range at index {k}");
        }
        assert_eq!(range_sum(&[], 0, 0), 0);
    }

    #[test]
    fn basic_ranges() {
        let a = [1, 2, 3, 4, 5];
        assert_eq!(range_sum(&a, 0, 5), 15); // full range
        assert_eq!(range_sum(&a, 0, 0), 0);
        assert_eq!(range_sum(&a, 5, 5), 0);
        assert_eq!(range_sum(&a, 2, 4), 7); // 3 + 4
        assert_eq!(range_sum(&a, 2, 3), 3); // single element
        assert_eq!(range_sum(&a, 0, 1), 1);
        assert_eq!(range_sum(&a, 4, 5), 5);
    }

    #[test]
    fn negatives_and_mixed() {
        let a = [-5, 10, -3, 7, -2];
        assert_eq!(range_sum(&a, 0, 5), 7);
        assert_eq!(range_sum(&a, 0, 3), 2);
        assert_eq!(range_sum(&a, 1, 1), 0);
        assert_eq!(range_sum(&a, 1, 4), 14);
        assert_eq!(range_sum(&a, 0, 1), -5);
    }

    #[test]
    fn extreme_magnitudes_fit_in_i64() {
        // Worst case per the domain: 1e6 elements each of magnitude 1e12
        // gives a sum of magnitude 1e18 < i64::MAX (~9.22e18).
        let n = 1_000_000usize;
        let big: Vec<i64> = vec![1_000_000_000_000; n];
        assert_eq!(range_sum(&big, 0, n), 1_000_000_000_000 * n as i64);
        assert_eq!(range_sum(&big, 123_456, n), 1_000_000_000_000 * (n - 123_456) as i64);

        let small: Vec<i64> = vec![-1_000_000_000_000; n];
        assert_eq!(range_sum(&small, 0, n), -1_000_000_000_000 * n as i64);

        // Mixed: positive half, negative half, total stays in range.
        let mixed: Vec<i64> = (0..n)
            .map(|k| if k < n / 2 { 1_000_000_000_000 } else { -1_000_000_000_000 })
            .collect();
        assert_eq!(range_sum(&mixed, 0, n), 0);
    }

    #[test]
    fn prefix_and_sub_ranges_are_consistent() {
        let a = [10i64, -4, 6, 0, -9, 3, 8, -2];
        // sum(a, 0, j) - sum(a, 0, i) == sum(a, i, j)
        for i in 0..a.len() {
            for j in i..a.len() {
                assert_eq!(
                    range_sum(&a, 0, j) - range_sum(&a, 0, i),
                    range_sum(&a, i, j),
                    "failed for i={i} j={j}"
                );
            }
        }
    }

    proptest! {
        #[test]
        fn matches_direct_fold(a in elems(300),
            p in 0usize..=300,
            q in 0usize..=300,
        ) {
            let (a, i, j) = valid_case(a, p, q);
            let expected = a[i..j].iter().fold(0i64, |s, &x| s.wrapping_add(x));
            assert_eq!(range_sum(&a, i, j), expected);
        }

        #[test]
        fn mirroring_negated_reversed_slice(a in elems(300),
            p in 0usize..=300,
            q in 0usize..=300,
        ) {
            let (a, i, j) = valid_case(a, p, q);
            // The sum of [i, j) of a equals the negative of the sum of the
            // corresponding mirrored range of the negated, reversed slice.
            let neg_rev: Vec<i64> = a.iter().map(|&x| -x).rev().collect();
            let n = a.len();
            assert_eq!(range_sum(&a, i, j), -range_sum(&neg_rev, n - j, n - i));
        }
    }
}

//! Finds the majority element of a slice, if one exists.
//!
//! A majority element is a value occurring in strictly more than `a.len() / 2`
//! positions of `a`. If no such value exists, `i64::MIN` is returned.

/// Returns the value occurring in strictly more than `a.len() / 2` positions
/// of `a`, or `i64::MIN` if no value does.
///
/// Uses the Boyer–Moore majority-vote algorithm: the first pass produces a
/// candidate, the second pass verifies its actual count. Runs in O(n) time
/// and O(1) extra space.
pub fn majority(a: &[i64]) -> i64 {
    // Pass 1: Boyer–Moore vote to find a candidate.
    let mut candidate = 0i64;
    let mut count: usize = 0;
    for &x in a {
        if count == 0 {
            candidate = x;
            count = 1;
        } else if x == candidate {
            count += 1;
        } else {
            count -= 1;
        }
    }

    // Pass 2: verify the candidate's true frequency.
    let occurrences = a.iter().filter(|&&x| x == candidate).count();
    if occurrences > a.len() / 2 {
        candidate
    } else {
        i64::MIN
    }
}

#[cfg(test)]
mod tests {
    use super::majority;
    use proptest::prelude::*;
    use std::collections::HashMap;

    fn brute_force(a: &[i64]) -> i64 {
        let mut freq: HashMap<i64, usize> = HashMap::new();
        for &x in a {
            *freq.entry(x).or_insert(0) += 1;
        }
        let mut best: Option<i64> = None;
        for (&v, &n) in &freq {
            if n > a.len() / 2 && best.map_or(true, |b| b < v) {
                best = Some(v);
            }
        }
        best.unwrap_or(i64::MIN)
    }

    #[test]
    fn empty_slice() {
        let a: &[i64] = &[];
        assert_eq!(majority(a), i64::MIN);
    }

    #[test]
    fn single_element_is_majority() {
        assert_eq!(majority(&[42]), 42);
        assert_eq!(majority(&[i64::MIN]), i64::MIN);
        assert_eq!(majority(&[i64::MAX]), i64::MAX);
        assert_eq!(majority(&[0]), 0);
        assert_eq!(majority(&[-1]), -1);
    }

    #[test]
    fn two_equal_elements() {
        assert_eq!(majority(&[7, 7]), 7);
    }

    #[test]
    fn two_distinct_elements_no_majority() {
        assert_eq!(majority(&[1, 2]), i64::MIN);
        assert_eq!(majority(&[i64::MIN, i64::MIN + 1]), i64::MIN);
    }

    #[test]
    fn majority_present() {
        assert_eq!(majority(&[1, 2, 1]), 1);
        assert_eq!(majority(&[5, 5, 5, 9]), 5);
        assert_eq!(majority(&[3, 8, 8, 1, 8]), 8);
        // 1 occurs 3 of 6: not strictly more than 3 -> no majority
        assert_eq!(majority(&[1, 2, 3, 1, 1, 2]), i64::MIN);
        // 1 occurs 4 of 6 -> majority
        assert_eq!(majority(&[1, 2, 3, 1, 1, 1]), 1);
    }

    #[test]
    fn even_length_needs_strict_majority() {
        // count 2 of 4 is not strictly more than 4 / 2 = 2
        assert_eq!(majority(&[1, 2, 1, 2]), i64::MIN);
        // count 3 of 4 is
        assert_eq!(majority(&[1, 2, 1, 1]), 1);
        // count 2 of 2 is
        assert_eq!(majority(&[9, 9]), 9);
    }

    #[test]
    fn no_majority_various() {
        assert_eq!(majority(&[1, 2, 3]), i64::MIN);
        assert_eq!(majority(&[1, 2, 3, 4]), i64::MIN);
        assert_eq!(majority(&[1, 2, 3, 1, 2, 3]), i64::MIN);
    }

    #[test]
    fn min_value_can_be_the_majority() {
        assert_eq!(majority(&[i64::MIN, i64::MIN]), i64::MIN);
        assert_eq!(majority(&[i64::MIN, 1, i64::MIN]), i64::MIN);
        assert_eq!(majority(&[i64::MIN, 1, 2]), i64::MIN);
    }

    #[test]
    fn long_repetitions() {
        let a = vec![10i64; 1_000_003];
        assert_eq!(majority(&a), 10);
        let mut b = vec![10i64; 1_000_000];
        b.push(11); // 10 occurs 1_000_000 of 1_000_001 -> majority
        assert_eq!(majority(&b), 10);
        let mut c = vec![10i64; 1_000_000];
        c.push(11);
        c.push(12); // 10 occurs 1_000_000 of 1_000_002 -> majority
        assert_eq!(majority(&c), 10);
        let mut d = vec![10i64; 500];
        for _ in 0..500 {
            d.push(20);
        } // 10 occurs 500 of 1000 -> not strictly more than 500
        assert_eq!(majority(&d), i64::MIN);
    }

    proptest! {
        #![proptest_config(ProptestConfig {
            cases: 400,
            max_shrink_iters: 200,
            ..ProptestConfig::default()
        })]

        // General agreement with the brute-force reference.
        #[test]
        fn matches_bruteforce_any(vec in prop::collection::vec(any::<i64>(), 0..200)) {
            prop_assert_eq!(majority(&vec), brute_force(&vec));
        }

        // Small alphabet makes majority collisions frequent.
        #[test]
        fn matches_bruteforce_small_alphabet(vec in prop::collection::vec(any::<i64>().prop_map(|x| x % 7 - 3), 0..200)) {
            prop_assert_eq!(majority(&vec), brute_force(&vec));
        }

        // Extreme values (i64::MIN / i64::MAX / neighbours / zero).
        #[test]
        fn matches_bruteforce_extremes(vec in prop::collection::vec(any::<u8>().prop_map(|b| match b & 3 {
            0 => i64::MIN,
            1 => i64::MAX,
            2 => i64::MIN + 1,
            _ => 0,
        }), 0..200)) {
            prop_assert_eq!(majority(&vec), brute_force(&vec));
        }

        // If a value truly holds a strict majority, it must be found.
        #[test]
        fn finds_guaranteed_majority(
            maj in any::<i64>(),
            rest in prop::collection::vec(any::<i64>(), 0..100),
        ) {
            // Interleave so `maj` occurs once per rest element plus one extra.
            let mut v: Vec<i64> = Vec::new();
            for x in rest.iter() {
                v.push(*x);
                v.push(maj);
            }
            v.push(maj);
            // maj count = rest.len()+1 > (2*rest.len()+1)/2 for all rest.len() >= 0
            prop_assert_eq!(majority(&v), maj);
        }
    }
}

/// Returns the length of the longest run of consecutive equal elements in `a`.
///
/// - `0` if the slice is empty,
/// - `1` if no two neighbours are equal (or the slice has a single element),
/// - otherwise the maximum run length.
pub fn longest_run(a: &[i64]) -> usize {
    if a.is_empty() {
        return 0;
    }
    let mut best = 1;
    let mut current = 1;
    for i in 1..a.len() {
        if a[i] == a[i - 1] {
            current += 1;
            if current > best {
                best = current;
            }
        } else {
            current = 1;
        }
    }
    best
}

#[cfg(test)]
mod tests {
    use super::longest_run;
    use proptest::prelude::*;

    #[test]
    fn empty() {
        assert_eq!(longest_run(&[]), 0);
    }

    #[test]
    fn single() {
        assert_eq!(longest_run(&[42]), 1);
    }

    #[test]
    fn no_equal_neighbours() {
        assert_eq!(longest_run(&[1, 2, 3, 4]), 1);
        assert_eq!(longest_run(&[1, 2]), 1);
    }

    #[test]
    fn all_equal() {
        assert_eq!(longest_run(&[7, 7, 7, 7]), 4);
    }

    #[test]
    fn runs_in_various_positions() {
        assert_eq!(longest_run(&[1, 1, 2, 2, 2, 3]), 3);
        assert_eq!(longest_run(&[1, 2, 2, 3, 3, 3]), 3);
        assert_eq!(longest_run(&[5, 5, 5, 1, 1]), 3);
        assert_eq!(longest_run(&[1, 2, 2, 2, 2, 3, 3]), 4);
    }

    #[test]
    fn negatives_and_extremes() {
        assert_eq!(longest_run(&[i64::MIN, i64::MIN, i64::MAX]), 2);
        assert_eq!(longest_run(&[0, 0, 0, 0, 0]), 5);
    }

    fn reference_longest_run(a: &[i64]) -> usize {
        if a.is_empty() {
            return 0;
        }
        let mut best = 1;
        let mut i = 0;
        while i < a.len() {
            let mut j = i;
            while j + 1 < a.len() && a[j] == a[j + 1] {
                j += 1;
            }
            best = best.max(j - i + 1);
            i = j + 1;
        }
        best
    }

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(2000))]

        // Few distinct values => frequently produces long runs.
        #[test]
        fn proptest_small_values(a in prop::collection::vec(-2i64..=2i64, 0..200)) {
            prop_assert_eq!(longest_run(&a), reference_longest_run(&a));
        }

        #[test]
        fn proptest_random(a in prop::collection::vec(any::<i64>(), 0..50)) {
            prop_assert_eq!(longest_run(&a), reference_longest_run(&a));
        }
    }
}

/// Merges two sorted (non-decreasing) slices `a` and `b` into `out`,
/// which must have length `a.len() + b.len()`. The merged result is
/// written into `out`, which will be sorted in non-decreasing order.
pub fn merge_sorted(a: &[i64], b: &[i64], out: &mut [i64]) {
    let mut i = 0; // index into a
    let mut j = 0; // index into b
    let mut k = 0; // index into out
    while i < a.len() && j < b.len() {
        if a[i] <= b[j] {
            out[k] = a[i];
            i += 1;
        } else {
            out[k] = b[j];
            j += 1;
        }
        k += 1;
    }
    // Copy whatever remains.
    for &v in &a[i..] {
        out[k] = v;
        k += 1;
    }
    for &v in &b[j..] {
        out[k] = v;
        k += 1;
    }
}

