            // Non-decreasing
            assert!(out.windows(2).all(|w| w[0] <= w[1]),
                    "out not sorted: {:?}", out);

            // Multiset equality: sorted(out) == a ++ b, sorted
            let mut expected: Vec<i64> = a.iter().copied().chain(b.iter().copied()).collect();
