        merge_sorted(&[], &[], &mut out);
        assert_eq!(out, Vec::<i64>::new());
    }

    #[test]
    fn unit_one_empty() {
        let a = [1, 2, 3];
        let mut out = [0i64; 3];
        merge_sorted(&a, &[], &mut out);
        assert_eq!(out, [1, 2, 3]);

        let mut out = [0i64; 3];
        merge_sorted(&[], &a, &mut out);
        assert_eq!(out, [1, 2, 3]);
    }

