//! In-place sorting of integer slices.

/// Sorts `a` into non-decreasing order, in place.
///
/// Uses an iterative (bottom-up) merge sort: O(n log n) time, O(n) auxiliary
/// space, stable, and safe for the full `i64` range (elements are compared
/// directly, never via subtraction).
pub fn sort(a: &mut [i64]) {
    let n = a.len();
    if n < 2 {
        return;
    }

    let mut aux = Vec::with_capacity(n);
    for &x in a.iter() {
        aux.push(x);
    }

    let mut width = 1usize;
    while width < n {
        // Distance between the starts of merged runs. While width <= n/2 it
        // is exactly 2 * width (no overflow); afterwards a single run covers
        // the whole slice, so stepping by n is equivalent.
        let stride = if width > n / 2 { n } else { width * 2 };
        for start in (0..n).step_by(stride) {
            let mid = start.saturating_add(width).min(n);
            let end = start
                .saturating_add(width)
                .saturating_add(width)
                .min(n);
            merge_runs(a, &aux, start, mid, end);
        }
        aux.copy_from_slice(a);
        // If width > n/2 the pass above merged the whole slice; otherwise
        // 2 * width <= n, so this multiplication cannot overflow.
        if width > n / 2 {
            break;
        }
        width *= 2;
    }
}

/// Merges the two sorted runs `src[lo..mid]` and `src[mid..hi]` into
/// `dst[lo..hi]` (the runs overlap in the caller's slice, but `src` and
/// `dst` are distinct buffers).
fn merge_runs(dst: &mut [i64], src: &[i64], lo: usize, mid: usize, hi: usize) {
    let mut i = lo;
    let mut j = mid;
    let mut k = lo;
    while i < mid && j < hi {
        if src[j] < src[i] {
            dst[k] = src[j];
            j += 1;
        } else {
            dst[k] = src[i];
            i += 1;
        }
        k += 1;
    }
    while i < mid {
        dst[k] = src[i];
        i += 1;
        k += 1;
    }
    while j < hi {
        dst[k] = src[j];
        j += 1;
        k += 1;
    }
}

