    fn many_lengths() {
        // Exercise boundaries where width crosses n/2 and run ends clip at n.
        for len in [2usize, 3, 4, 5, 6, 7, 8, 15, 16, 17, 31, 32, 33, 64, 100,
                   127, 128, 129, 255, 256, 257, 1000, 1023, 1024, 1025] {
            // Reverse-sorted permutation of 0..len.
            let mut v: Vec<i64> = (0..len)
                .map(|i| (len - 1 - i) as i64)
                .collect();
