//! Modular exponentiation: exact computation of `base^exp mod m`.

/// Returns `(base^exp) mod m`, computed exactly, with the result in `[0, m)`.
///
/// Input domain: `base >= 0`, `exp >= 0`, `1 <= m <= 3_000_000_000`
/// (base and exp may be as large as `i64::MAX`).
///
/// `0^0` is defined as 1, so `pow_mod(0, 0, m) == 1 % m`
/// (i.e. `1` for `m > 1` and `0` for `m == 1`).
///
/// Intermediate products are formed in `u128` so the computation is exact
/// and cannot overflow, regardless of the sizes of `base` and `exp`.
pub fn pow_mod(base: i64, exp: i64, m: i64) -> i64 {
    debug_assert!(base >= 0 && exp >= 0 && m >= 1);
    let m128 = m as u128;
    let mut result: u128 = 1 % m128; // 1 % 1 == 0, handling m == 1
    let mut b = (base as u128) % m128;
    let mut e = exp as u128;
    while e > 0 {
        if (e & 1) == 1 {
            result = (result * b) % m128;
        }
        b = (b * b) % m128;
        e >>= 1;
    }
    result as i64
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    /// Straight-line reference: multiply `exp` times (exact in u128).
    fn naive_pow_mod(base: i64, exp: i64, m: i64) -> i64 {
        let m = m as u128;
        let mut r = 1u128 % m;
        let b = (base as u128) % m;
        for _ in 0..exp {
            r = (r * b) % m;
        }
        r as i64
    }

    /// Independent implementation: most-significant-bit-first square-and-multiply.
    fn msb_pow_mod(base: i64, exp: i64, m: i64) -> i64 {
        let m128 = m as u128;
        let b = (base as u128) % m128;
        let mut r: u128 = 1;
        for i in (0..63).rev() {
            r = (r * r) % m128;
            if ((exp >> i) & 1) == 1 {
                r = (r * b) % m128;
            }
        }
        r as i64
    }

    #[test]
    fn known_values() {
        assert_eq!(pow_mod(2, 10, 1000), 24);
        assert_eq!(pow_mod(3, 20, 100), 1);
        assert_eq!(pow_mod(7, 0, 3), 1);
        assert_eq!(pow_mod(10, 1, 1000), 10);
        assert_eq!(pow_mod(10, 2, 1000), 100);
        assert_eq!(pow_mod(10, 3, 1000), 0);
    }

    #[test]
    fn zero_exponent_and_zero_base() {
        // 0^0 = 1, so result is 1 mod m
        assert_eq!(pow_mod(0, 0, 1), 0);
        assert_eq!(pow_mod(0, 0, 2), 1);
        assert_eq!(pow_mod(0, 0, 3_000_000_000), 1);
        assert_eq!(pow_mod(123, 0, 1), 0);
        assert_eq!(pow_mod(123, 0, 5), 1);
        assert_eq!(pow_mod(i64::MAX, 0, 999_999_937), 1);
        // 0^e = 0 for e > 0
        assert_eq!(pow_mod(0, 1, 5), 0);
        assert_eq!(pow_mod(0, i64::MAX, 5), 0);
        assert_eq!(pow_mod(0, i64::MAX, 1), 0);
    }

    #[test]
    fn modulus_one_is_always_zero() {
        assert_eq!(pow_mod(0, 0, 1), 0);
        assert_eq!(pow_mod(5, 7, 1), 0);
        assert_eq!(pow_mod(i64::MAX, i64::MAX, 1), 0);
    }

    #[test]
    fn extreme_domain_edges() {
        let m = 3_000_000_000;
        // base == m (reduces to 0), large exp
        assert_eq!(pow_mod(m, i64::MAX, m), 0);
        // base reduced mod m, small exp checked against exact naive
        assert_eq!(pow_mod(i64::MAX, 2, m), naive_pow_mod(i64::MAX, 2, m));
        // (-1)^e mod m pattern
        for e in [0i64, 1, 2, i64::MAX - 1, i64::MAX] {
            let expected = if e % 2 == 0 { 1 % m } else { m - 1 };
            assert_eq!(pow_mod(m - 1, e, m), expected);
        }
        // base = 1 is always 1 mod m
        assert_eq!(pow_mod(1, i64::MAX, m), 1);
        assert_eq!(pow_mod(1, i64::MAX, 1), 0);
        // max base, max exp, max m: result must be in [0, m)
        let r = pow_mod(i64::MAX, i64::MAX, m);
        assert!((0..m).contains(&r));
    }

    #[test]
    fn cross_check_all_ranges_of_exp_magnitude() {
        // Compare the three implementations across a sweep of exp sizes,
        // including full i64::MAX, and a few moduli near the 3e9 limit
        // (where (m-1)^2 is closest to i64::MAX).
        let moduli = [1i64, 2, 3, 999_999_937, 2_147_483_647, 2_999_999_999, 3_000_000_000];
        let bases = [0i64, 1, 2, 3_000_000_001, i64::MAX];
        let exps = [
            0i64, 1, 2, 3, 63, 64, 65, 100, 1_000, 1_000_000, i64::MAX - 1, i64::MAX,
        ];
        for &m in &moduli {
            for &b in &bases {
                for &e in &exps {
                    let got = pow_mod(b, e, m);
                    let msb = msb_pow_mod(b, e, m);
                    assert_eq!(got, msb, "mismatch for b={b} e={e} m={m}");
                    assert!((0..m).contains(&got), "out of range for b={b} e={e} m={m}");
                    if e <= 100_000 {
                        let naive = naive_pow_mod(b, e, m);
                        assert_eq!(got, naive, "mismatch vs naive for b={b} e={e} m={m}");
                    }
                }
            }
        }
    }

    proptest! {
        // Exact check against i128 integer power (fits: 999^11 < 2^127).
        #[test]
        fn exact_small(base in 0..1000i64, exp in 0..12i64, m in 1..100_000i64) {
            let expected = (base as i128).pow(exp as u32) % m as i128;
            prop_assert_eq!(pow_mod(base, exp, m), expected as i64);
        }

        // Full domain of base/m, moderate exp: compare with naive loop.
        #[test]
        fn naive_medium(base in 0..=3_000_000_000i64, exp in 0..2000i64, m in 1..=3_000_000_000i64) {
            prop_assert_eq!(pow_mod(base, exp, m), naive_pow_mod(base, exp, m));
        }

        // Full input domain incl. i64::MAX exp/base: compare with an
        // independent MSB-first implementation; result must be in [0, m).
        #[test]
        fn large_domain(base in 0i64..=i64::MAX, exp in 0i64..=i64::MAX, m in 1..=3_000_000_000i64) {
            let r = pow_mod(base, exp, m);
            prop_assert_eq!(r, msb_pow_mod(base, exp, m));
            prop_assert!((0..m).contains(&r));
        }

        // a^(e1+e2) mod m == (a^e1 mod m * a^e2 mod m) mod m
        #[test]
        fn additivity(a in 0..=3_000_000_000i64, e1 in 0i64..=i64::MAX, e2 in 0i64..=i64::MAX, m in 1..=3_000_000_000i64) {
            let s = match e1.checked_add(e2) {
                Some(s) => s,
                None => return Ok(()), // exponent sum beyond domain; skip
            };
            let prod = ((pow_mod(a, e1, m) as u128) * (pow_mod(a, e2, m) as u128) % m as u128) as i64;
            prop_assert_eq!(prod, pow_mod(a, s, m));
        }

        // (a^e1)^e2 mod m == a^(e1*e2) mod m, checked against the naive loop.
        #[test]
        fn power_of_power(a in 0..=3_000_000_000i64, e1 in 0i64..100, e2 in 0i64..100, m in 1..=3_000_000_000i64) {
            prop_assert_eq!(
                pow_mod(pow_mod(a, e1, m), e2, m),
                naive_pow_mod(a, e1 * e2, m)
            );
        }

        // (a*b)^e mod m == (a^e mod m * b^e mod m) mod m
        #[test]
        fn multiplicativity(a in 0..=3_000_000_000i64, b in 0..=3_000_000_000i64, e in 0i64..=i64::MAX, m in 1..=3_000_000_000i64) {
            let ab = ((a as u128) * (b as u128) % m as u128) as i64;
            let lhs = ((pow_mod(a, e, m) as u128) * (pow_mod(b, e, m) as u128) % m as u128) as i64;
            prop_assert_eq!(lhs, pow_mod(ab, e, m));
        }
    }
}
